window.__Q=window.__Q||{};window.__Q["prev/2/B1"]=[{"q":"具有齿突的椎骨是","o":["寰椎","枢椎","隆椎","胸椎","腰椎"],"a":1,"e":"枢椎为第2颈椎，椎体向上伸出齿突，与寰椎前弓后面的齿突凹相关节、构成寰枢正中关节，参与头部的旋转运动。寰椎为第1颈椎、呈环状、无椎体和棘突，前弓后面有齿突凹；隆椎为第7颈椎、棘突长且末端不分叉，为计数椎骨的标志；胸椎有肋凹；腰椎椎体粗壮"},{"q":"有前弓、后弓和侧板组成，前弓后面有齿突凹的椎骨是","o":["寰椎","枢椎","隆椎","胸椎","腰椎"],"a":0,"e":"寰椎为第1颈椎，呈环状，无椎体、棘突和关节突，由前弓、后弓及侧块组成，前弓较短、后面正中有齿突凹与枢椎齿突相关节，侧块上方接枕髁、下方接枢椎上关节面。枢椎有齿突；隆椎棘突长、末端不分叉；胸椎有肋凹；腰椎椎体粗壮、横断面肾形"},{"q":"棘突特别长，末端不分叉，活体易于摸到，为记数椎骨序数的标志的椎骨是","o":["寰椎","枢椎","隆椎","胸椎","腰椎"],"a":2,"e":"隆椎为第7颈椎，棘突长、末端不分叉，活体易于触及，常作为计数椎骨序数的标志。寰椎呈环状、无棘突；枢椎有齿突；胸椎棘突细长、呈叠瓦状倾斜；腰椎椎体粗壮、棘突宽短呈板状，均非计数标志"},{"q":"呈环状，无椎体、棘突和关节突的椎骨是","o":["寰椎","枢椎","隆椎","胸椎","腰椎"],"a":0,"e":"寰椎为第1颈椎，呈环状，无椎体、棘突和关节突，由前弓、后弓及侧块组成。枢椎有椎体和齿突；隆椎棘突长、末端不分叉；胸椎椎体呈心形、有肋凹；腰椎椎体粗壮、横断面呈肾形，这些椎骨均有椎体和棘突"},{"q":"鼻泪管开口于","o":["上鼻道","中鼻道","下鼻道","蝶筛隐窝","半月裂孔"],"a":2,"e":"鼻泪管向下开口于下鼻道前上方，流泪时泪液经此流入鼻腔。上鼻道有筛窦后群开口，中鼻道有额窦、上颌窦和前筛窦开口。泪点为泪小管起始处，泪囊位于泪囊窝内，均非鼻泪管的开口部位。鼻泪管上接泪囊，下段位于骨性鼻泪管内，开口处黏膜静脉丛丰富"},{"q":"额窦开口于","o":["上鼻道","中鼻道","下鼻道","蝶筛隐窝","半月裂孔"],"a":1,"e":"额窦居眉弓深面，窦口向后下，开口于中鼻道前部的筛漏斗处。上颌窦开口于中鼻道的半月裂孔；筛窦前、中群开口于中鼻道、后群开口于上鼻道；蝶窦开口于蝶筛隐窝；下鼻道有鼻泪管开口。本题选项中的半月裂孔是上颌窦开口所在，额窦则开口于筛漏斗，故归中鼻道"},{"q":"蝶窦开口于","o":["上鼻道","中鼻道","下鼻道","蝶筛隐窝","半月裂孔"],"a":3,"e":"蝶窦位于蝶骨体内，被中隔分为左右两腔，各自向前开口于上鼻甲后上方的蝶筛隐窝。额窦、上颌窦与筛窦前群、中群均开口于中鼻道，下鼻道承接鼻泪管开口，上鼻甲下方即上鼻道，主要接受后筛窦"},{"q":"上颌窦开口于","o":["上鼻道","中鼻道","下鼻道","蝶筛隐窝","半月裂孔"],"a":1,"e":"上颌窦位于上颌骨体内，开口于中鼻道的半月裂孔，因开口位置较高、分泌物不易排出，窦腔积液时需体位引流。额窦开口于中鼻道前部的筛漏斗；筛窦前、中群开口于中鼻道、后群开口于上鼻道；蝶窦开口于蝶筛隐窝；下鼻道有鼻泪管开口"},{"q":"受损后致眼内斜视的神经核是","o":["动眼神经核","动眼神经副核","滑车神经核","展神经核","三叉神经感觉核"],"a":3,"e":"展神经核发出纤维支配外直肌使眼球外展，受损后外直肌麻痹、眼球不能外展，因内直肌相对占优势而出现眼内斜视。动眼神经核受损致眼外斜视、上睑下垂；动眼神经副核受损致瞳孔散大、对光反射消失；滑车神经核受损致眼不能外下斜视；三叉神经感觉核与眼球运动无关"},{"q":"与角膜反射有关的神经核是","o":["动眼神经核","动眼神经副核","滑车神经核","展神经核","三叉神经感觉核"],"a":4,"e":"角膜反射的传入神经为眼神经（三叉神经第一支），感觉冲动终止于三叉神经感觉核，传出为面神经核支配眼轮匝肌闭眼，故与三叉神经感觉核相关。动眼神经核支配眼外肌；动眼神经副核司瞳孔括约肌、睫状肌；滑车神经核支配上斜肌；展神经核支配外直肌"},{"q":"发出纤维支配上斜肌的神经核是","o":["动眼神经核","动眼神经副核","滑车神经核","展神经核","三叉神经感觉核"],"a":2,"e":"滑车神经核位于中脑下丘高度，发出纤维组成滑车神经，自中脑下丘下方出脑、绕大脑脚外侧前行入眶，支配上斜肌使瞳孔转向下外方。动眼神经核支配上、下、内直肌、下斜肌和上睑提肌；动眼神经副核支配瞳孔括约肌、睫状肌；展神经核支配外直肌；三叉神经感觉核为感觉核"},{"q":"受损后致瞳孔散大的神经核是","o":["动眼神经核","动眼神经副核","滑车神经核","展神经核","三叉神经感觉核"],"a":1,"e":"动眼神经副核（E-W核）发出副交感节前纤维，经睫状神经节换元后支配瞳孔括约肌和睫状肌，受损后瞳孔括约肌麻痹、瞳孔散大，对光及调节反射消失。动眼神经核受损致眼外斜视、上睑下垂；滑车神经核受损致眼不能外下斜视；展神经核受损致眼内斜视；三叉神经感觉核与瞳孔无关"},{"q":"滑车神经","o":["混合性神经","感觉性神经","运动性神经","交感神经","副交感神经"],"a":2,"e":"滑车神经为运动性脑神经，只含一般躯体运动纤维，起自中脑滑车神经核，支配上斜肌。混合性神经如三叉神经、面神经、舌咽神经和迷走神经兼含感觉与运动纤维；感觉性神经如嗅神经、视神经和前庭蜗神经；交感和副交感属内脏运动神经，均不是滑车神经的性质"},{"q":"下颌神经","o":["混合性神经","感觉性神经","运动性神经","交感神经","副交感神经"],"a":0,"e":"下颌神经为三叉神经第三支，属混合性神经，含一般躯体感觉纤维和特殊内脏运动纤维，经卵圆孔出颅，支配咀嚼肌并传导下颌、舌前2/3等处感觉。感觉性神经如上颌神经和眼神经只含感觉纤维；运动性神经如滑车神经和展神经；交感和副交感为内脏运动神经"},{"q":"上颌神经","o":["混合性神经","感觉性神经","运动性神经","交感神经","副交感神经"],"a":1,"e":"上颌神经为三叉神经第二支，属感觉性神经，只含一般躯体感觉纤维，经圆孔出颅，分布于上颌牙、鼻腔和面部皮肤等。混合性神经如下颌神经兼含运动和感觉纤维；运动性神经如展神经和滑车神经支配眼外肌；交感和副交感为内脏运动神经，支配平滑肌、心肌和腺体"},{"q":"甲状颈干起自","o":["桡动脉","尺动脉","颈外动脉","锁骨下动脉","上颌动脉"],"a":3,"e":"甲状颈干为锁骨下动脉的分支，起于锁骨下动脉前壁，主要发出甲状腺下动脉、肩胛上动脉、肋颈干等，分布于甲状腺和肩胛区等处。桡动脉、尺动脉为肱动脉的终支；颈外动脉起自颈总动脉分叉处；上颌动脉为颈外动脉的终支之一"},{"q":"面动脉起自","o":["桡动脉","尺动脉","颈外动脉","锁骨下动脉","上颌动脉"],"a":2,"e":"面动脉是颈外动脉前壁发出的分支，经下颌下腺深面绕下颌骨下缘至面部，分布于面颊、鼻背和口唇。甲状颈干起自锁骨下动脉，发出甲状腺下动脉、肩胛上动脉等；颈内动脉在颈部无任何分支，不可能发出面动脉"},{"q":"脑膜中动脉起自","o":["桡动脉","尺动脉","颈外动脉","锁骨下动脉","上颌动脉"],"a":4,"e":"脑膜中动脉为上颌动脉的分支，在下颌颈深面发出，向上穿棘孔入颅，分前、后支紧贴颅骨内面走行，分布于颅骨和硬脑膜，前支经翼点内面、颞部骨折易损伤致硬膜外血肿。桡、尺动脉分布于上肢；颈外动脉是上颌动脉的母动脉；锁骨下动脉为上肢和颈部动脉主干"},{"q":"掌深弓的构成包括","o":["桡动脉","尺动脉","颈外动脉","锁骨下动脉","上颌动脉"],"a":0,"e":"掌深弓由桡动脉末端与尺动脉掌深支吻合而成，位于指深屈肌腱深面、约平腕掌关节高度，发出3支掌心动脉。掌浅弓由尺动脉末端与桡动脉掌浅支吻合而成。本题以桡动脉末端直接构成掌深弓；颈外动脉、锁骨下动脉、上颌动脉均不参与手部动脉弓的构成"},{"q":"掌浅弓的构成包括","o":["桡动脉","尺动脉","颈外动脉","锁骨下动脉","上颌动脉"],"a":1,"e":"掌浅弓由尺动脉末端与桡动脉掌浅支吻合而成，位于掌腱膜深面，发出指掌侧总动脉。掌深弓由桡动脉末端与尺动脉掌深支吻合而成，位于指深屈肌腱深面。本题以尺动脉末端构成掌浅弓为主；桡动脉末端构成掌深弓；颈外动脉、锁骨下动脉、上颌动脉均不参与手弓"},{"q":"胰十二指肠上动脉起自","o":["腹腔干","肝总动脉","脾动脉","肠系膜上动脉","胃十二指肠动脉"],"a":4,"e":"胃十二指肠动脉为肝总动脉的分支，经十二指肠上部、幽门后方至胃下缘，分为胃网膜右动脉和胰十二指肠上动脉，后者与胰十二指肠下动脉吻合、营养胰和十二指肠。胰十二指肠下动脉起自肠系膜上动脉；腹腔干分胃左、肝总、脾三支；脾动脉发出胃短动脉等"},{"q":"胃后动脉起自","o":["腹腔干","肝总动脉","脾动脉","肠系膜上动脉","胃十二指肠动脉"],"a":2,"e":"胃后动脉多起自脾动脉主干或其分支，经胃膈韧带至胃后壁，供应胃体后壁上部。胃左动脉起自腹腔干、沿胃小弯右行；胃右动脉起自肝固有动脉、沿胃小弯左行；胃网膜右动脉起自胃十二指肠动脉、沿胃大弯；肠系膜上动脉供应中肠"},{"q":"右结肠动脉起自","o":["腹腔干","肝总动脉","脾动脉","肠系膜上动脉","胃十二指肠动脉"],"a":3,"e":"右结肠动脉起自肠系膜上动脉，向右行供应升结肠，与中结肠动脉、回结肠动脉的分支吻合。中结肠动脉和胰十二指肠下动脉亦起自肠系膜上动脉；腹腔干的分支供应前肠（胃、肝、脾等）；胃十二指肠动脉为肝总动脉的分支，发出胰十二指肠上动脉等"},{"q":"胃右动脉起自","o":["腹腔干","肝总动脉","脾动脉","肠系膜上动脉","胃十二指肠动脉"],"a":1,"e":"胃右动脉多起自肝固有动脉（肝总动脉的延续），沿胃小弯左行与胃左动脉吻合、供应胃小弯胃壁。胃左动脉直接起自腹腔干；脾动脉发出胃短动脉、胃网膜左动脉；胃十二指肠动脉为肝总动脉分支、发出胃网膜右动脉；肠系膜上动脉供应中肠"},{"q":"胃网膜右动脉起自","o":["腹腔干","肝总动脉","脾动脉","肠系膜上动脉","胃十二指肠动脉"],"a":4,"e":"胃十二指肠动脉经十二指肠上部后方下行，至胃下缘分为胃网膜右动脉和胰十二指肠上动脉。A项胰十二指肠上动脉为其分支而非来源；C项胃网膜左动脉起自脾动脉；D项胃右动脉起自肝固有动脉；E项肠系膜上动脉发出胰十二指肠下动脉"},{"q":"参与形成脉络丛的是","o":["硬脑膜","硬脊膜","软脊膜","脊髓蛛网膜","软脑膜"],"a":4,"e":"脉络丛由软脑膜及其血管与室管膜上皮共同突入脑室形成，软脑膜薄而富有血管和神经，覆盖脑表面并伸入沟裂。硬脑膜厚而坚韧并形成大脑镰、小脑幕等；硬脊膜和脊髓蛛网膜为脊髓被膜；软脊膜紧贴脊髓表面，不参与脑室脉络丛的构成"},{"q":"齿状韧带形成于","o":["硬脑膜","硬脊膜","软脊膜","脊髓蛛网膜","软脑膜"],"a":2,"e":"软脊膜薄而富含血管，紧贴脊髓表面并伸入沟裂，在脊髓两侧、脊神经前根与后根之间向外突出形成齿状韧带，其尖端附于硬脊膜，起固定脊髓的作用。硬脊膜与椎管骨膜之间为硬膜外隙。脊髓蛛网膜与软脊膜之间为蛛网膜下隙。齿状韧带并非由蛛网膜形成"},{"q":"小脑幕形成于","o":["硬脑膜","硬脊膜","软脊膜","脊髓蛛网膜","软脑膜"],"a":0,"e":"小脑幕由硬脑膜内层折叠形成，呈半月形伸入大脑横裂，分隔大脑与小脑，大脑镰亦由硬脑膜形成。硬脊膜为脊髓被膜；软脊膜紧贴脊髓表面；脊髓蛛网膜位于硬脊膜与软脊膜之间；软脑膜薄而富血管并参与构成脉络丛，均不形成小脑幕"},{"q":"有屈光作用的是","o":["巩膜","角膜","虹膜","脉络膜","视网膜"],"a":1,"e":"角膜占眼球纤维膜的前1/6，无色透明、富有弹性，曲度较大、外凸内凹，具有屈光作用，与房水、晶状体、玻璃体合称眼的屈光装置。巩膜占后5/6、乳白不透明，起保护支持作用；虹膜调节入眼光线；脉络膜营养并吸收散射光；视网膜为感光层"},{"q":"有感光作用的是","o":["巩膜","角膜","虹膜","脉络膜","视网膜"],"a":4,"e":"视网膜为眼球内膜，其脉络膜部（视部）含视锥细胞和视杆细胞，具有感光作用；虹膜部和睫状体部薄而无感光作用、称盲部。角膜无色透明、具屈光作用；巩膜不透明、保护支持；虹膜通过瞳孔调节入眼光量；脉络膜富含血管色素、营养并吸收散射光"},{"q":"可调节进入眼内光线的是","o":["巩膜","角膜","虹膜","脉络膜","视网膜"],"a":2,"e":"虹膜中央有瞳孔，内含瞳孔括约肌（副交感、缩瞳）和瞳孔开大肌（交感、散瞳），弱光或视远时瞳孔开大、强光或视近时缩小，从而调节进入眼内的光线量。角膜主司屈光；巩膜保护支持；脉络膜吸收散射光、营养眼内；视网膜为感光层"},{"q":"可吸收散射光线的是","o":["巩膜","角膜","虹膜","脉络膜","视网膜"],"a":3,"e":"脉络膜占血管膜的后2/3，富含血管及色素，外面与巩膜疏松相连、内面紧贴视网膜色素层，营养眼球内组织并吸收分散（散射）光线。角膜无色透明、具屈光作用；巩膜乳白不透明、保护支持；虹膜通过瞳孔调节入眼光量；视网膜为感光层"},{"q":"颈外静脉注入","o":["腋静脉","锁骨下静脉","头臂静脉","上腔静脉","颈内静脉"],"a":1,"e":"颈外静脉由下颌后静脉后支、耳后静脉和枕静脉在下颌角处汇合而成，沿胸锁乳突肌表面下行，穿深筋膜注入锁骨下静脉或静脉角。颈内静脉与锁骨下静脉汇合成头臂静脉；腋静脉在第1肋外侧缘续为锁骨下静脉；上腔静脉由左右头臂静脉汇合"},{"q":"头静脉注入","o":["腋静脉","锁骨下静脉","头臂静脉","上腔静脉","颈内静脉"],"a":0,"e":"头静脉起自手背静脉网桡侧，经三角肌胸大肌间沟至锁骨下窝，穿深筋膜主要注入腋静脉，是上肢重要的浅静脉。锁骨下静脉主要接受腋静脉和颈外静脉，头静脉仅少数注入此；头臂静脉由颈内与锁骨下静脉汇合；上腔静脉由左右头臂静脉合成"},{"q":"奇静脉注入","o":["腋静脉","锁骨下静脉","头臂静脉","上腔静脉","颈内静脉"],"a":3,"e":"奇静脉起自右腰升静脉，沿胸主动脉右侧上行，至第4胸椎高度勾绕右肺根上方注入上腔静脉，并沟通上、下腔静脉系。半奇静脉注入奇静脉而非上腔静脉；上腔静脉由左右头臂静脉汇合而成；头臂静脉由颈内静脉与锁骨下静脉合成"},{"q":"位于颅前窝并通向鼻腔的结构是","o":["卵圆孔","圆孔","眶上裂","筛孔","内耳门"],"a":3,"e":"筛孔位于颅前窝的筛板上，嗅神经的嗅丝穿此孔入颅前窝连于嗅球，向下通鼻腔。卵圆孔和圆孔位于颅中窝，分别通颞下窝和翼腭窝；眶上裂位于颅中窝通眶；内耳门位于颅后窝，为前庭蜗神经和面神经出颅处"},{"q":"位于颅中窝并通向颞下窝的结构是","o":["卵圆孔","圆孔","眶上裂","筛孔","内耳门"],"a":0,"e":"卵圆孔位于蝶骨大翼根部，属颅中窝，向下通颞下窝，有下颌神经通过。圆孔位于颅中窝并向后通翼腭窝，有上颌神经通过；眶上裂通眶，有动眼、滑车、展神经及眼神经通过；筛孔位于颅前窝通鼻腔；内耳门位于颅后窝"},{"q":"位于颅中窝并通向翼腭窝的结构是","o":["卵圆孔","圆孔","眶上裂","筛孔","内耳门"],"a":1,"e":"圆孔位于蝶骨大翼根部，属颅中窝，向后通翼腭窝，有上颌神经通过。卵圆孔位于颅中窝并向下通颞下窝，有下颌神经通过；眶上裂通眶；筛孔在颅前窝通鼻腔；内耳门在颅后窝通内耳道，均不连翼腭窝"},{"q":"将器官固定于腹、盆壁的双层腹膜结构称为","o":["系膜","韧带","腹膜隐窝","腹膜襞","腹膜陷凹"],"a":0,"e":"系膜由壁、脏腹膜相互延续移行形成，为双层腹膜结构，将器官系连固定于腹、盆壁，内含出入器官的血管、神经、淋巴管和淋巴结，如肠系膜、阑尾系膜等。韧带为连接腹盆壁与脏器或相邻脏器的腹膜结构；腹膜襞为腹膜隆起；隐窝、陷凹为腹膜凹陷"},{"q":"脏器之间或脏器与腹、盆壁之间的腹膜形成的隆起称为","o":["系膜","韧带","腹膜隐窝","腹膜襞","腹膜陷凹"],"a":3,"e":"腹膜襞为脏器之间或脏器与腹、盆壁之间腹膜形成的隆起，深部常有血管走行。系膜为将器官固定于腹盆壁的双层腹膜；韧带为连接脏器与腹盆壁或相邻脏器的腹膜结构；腹膜隐窝为腹膜襞之间或其与腹盆壁之间的凹陷；陷凹为较大的隐窝"},{"q":"连接腹、盆壁与脏器之间或相邻脏器之间的腹膜结构称为","o":["系膜","韧带","腹膜隐窝","腹膜襞","腹膜陷凹"],"a":1,"e":"腹膜形成的韧带指连接腹、盆壁与脏器之间或连接相邻脏器之间的腹膜结构，多数为双层、少数单层，对脏器有固定作用，有的含血管神经。系膜为将器官系连固定于腹盆壁的双层腹膜；腹膜襞为腹膜隆起；腹膜隐窝、陷凹为腹膜的凹陷"},{"q":"鼓室的外侧壁也称","o":["盖壁","鼓膜壁","迷路壁","颈动脉壁","颈静脉壁"],"a":1,"e":"鼓室外侧壁大部分由鼓膜构成，故又名鼓膜壁。上壁由鼓室盖构成、称盖壁，分隔鼓室与颅中窝；内侧壁与内耳相隔、称迷路壁；前壁为颈动脉管的后壁、称颈动脉壁；下壁为薄骨板、分隔颈静脉窝、称颈静脉壁"},{"q":"鼓室的内侧壁也称","o":["盖壁","鼓膜壁","迷路壁","颈动脉壁","颈静脉壁"],"a":2,"e":"鼓室内侧壁与内耳相隔，称迷路壁，其上有岬、前庭窗、蜗窗和面神经管凸等结构。鼓膜壁为外侧壁、大部分由鼓膜构成；盖壁为上壁、由鼓室盖构成并分隔颅中窝；颈动脉壁为前壁、分隔颈内动脉；颈静脉壁为下壁、分隔颈静脉窝"},{"q":"鼓室的前壁也称","o":["盖壁","鼓膜壁","迷路壁","颈动脉壁","颈静脉壁"],"a":3,"e":"鼓室前壁为颈动脉管的后壁，称颈动脉壁，此壁甚薄、借骨板分隔鼓室与颈内动脉，上部有鼓膜张肌半管和咽鼓管半管。迷路壁为内侧壁、与内耳相隔；鼓膜壁为外侧壁；盖壁为上壁；颈静脉壁为下壁、分隔颈静脉窝"},{"q":"鼓室的下壁也称","o":["盖壁","鼓膜壁","迷路壁","颈动脉壁","颈静脉壁"],"a":4,"e":"鼓室下壁亦称颈静脉壁，为一薄层骨板，分隔鼓室与颈静脉窝内的颈静脉球。盖壁为上壁、由鼓室盖构成并分隔颅中窝；鼓膜壁为外侧壁、由鼓膜构成；迷路壁为内侧壁、与内耳相隔；颈动脉壁为前壁、分隔颈内动脉"},{"q":"组成乳突的骨是","o":["颞骨","蝶骨","筛骨","额骨","枕骨"],"a":0,"e":"乳突为颞骨岩部后下方的突起，内含乳突小房，中耳炎可经乳突窦侵犯乳突小房引起乳突炎，耳内手术可经乳突小房入路。蝶骨构成颅底并发出翼突；筛骨参与构成鼻腔外侧壁；额骨构成颅前窝；枕骨构成颅后窝，均不形成乳突"},{"q":"组成翼突的骨是","o":["颞骨","蝶骨","筛骨","额骨","枕骨"],"a":1,"e":"翼突为蝶骨大翼根部向下的突起，分翼内板和翼外板，翼内肌起自翼突窝，翼外肌起自翼突外侧面，翼上颌裂位于上颌骨与蝶骨翼突之间。颞骨容纳中耳内耳并有乳突；筛骨迷路形成上、中鼻甲；额骨构成颅前窝；枕骨参与颅后窝构成，均不形成翼突"},{"q":"组成中鼻甲的骨是","o":["颞骨","蝶骨","筛骨","额骨","枕骨"],"a":2,"e":"中鼻甲为筛骨迷路内侧壁向下卷曲的薄骨片覆以黏膜而成，上鼻甲亦由筛骨构成。颞骨容纳中耳与内耳；蝶骨发出翼突；额骨构成颅前窝；枕骨构成颅后窝，均不参与鼻甲构成，下鼻甲则为独立的一对骨"},{"q":"组成茎乳孔的骨是","o":["颞骨","蝶骨","筛骨","额骨","枕骨"],"a":0,"e":"茎乳孔位于颞骨茎突根部后方，是面神经出颅的部位，乳突、内耳门也位于颞骨。蝶骨有卵圆孔、圆孔和棘孔；筛骨有筛孔；额骨有盲孔；枕骨有枕髁、舌下神经管外口及颈静脉孔的一部分，均不形成茎乳孔"},{"q":"垂体后叶分泌功能低下可引起","o":["侏儒症","子宫收缩、乳腺泌乳","巨人症","手足搐搦症","尿崩症"],"a":4,"e":"垂体后叶（神经部）贮存并释放视上核、室旁核合成的抗利尿激素和缩宫素，抗利尿激素促进肾远曲小管和集合管重吸收水、使尿液浓缩，分泌减少即致尿崩症。侏儒症为幼年生长激素不足；巨人症为幼年生长激素过多；手足搐搦症为甲状旁腺功能低下；子宫收缩、泌乳为缩宫素作用"},{"q":"甲状旁腺功能低下可引起","o":["侏儒症","子宫收缩、乳腺泌乳","巨人症","手足搐搦症","尿崩症"],"a":3,"e":"甲状旁腺分泌甲状旁腺激素调节钙磷代谢，分泌不足致血钙降低、机体酸中毒，引起中枢神经和肌肉功能紊乱，表现为手足搐搦症。侏儒症、巨人症分别为幼年生长激素不足或过多；尿崩症为抗利尿激素减少；子宫收缩、乳腺泌乳为缩宫素的作用"},{"q":"垂体前叶分泌功能过剩可引起","o":["侏儒症","子宫收缩、乳腺泌乳","巨人症","手足搐搦症","尿崩症"],"a":2,"e":"垂体前叶（腺垂体）分泌生长激素，幼年分泌过多、在骨骼发育成熟前即引起巨人症，成年后过多则致肢端肥大症。侏儒症为幼年生长激素不足；尿崩症为抗利尿激素（垂体后叶）减少；手足搐搦症为甲状旁腺功能低下；子宫收缩、泌乳为缩宫素的作用"},{"q":"舌下神经的出脑部位为","o":["延髓脑桥沟","脚间窝","前外侧沟","脑桥臂","中脑背面"],"a":2,"e":"舌下神经根丝自延髓锥体与橄榄之间的前外侧沟出脑，支配舌内、外肌。延髓脑桥沟自中线向外依次连展神经、面神经、前庭蜗神经；脚间窝为动眼神经出脑处；中脑下丘下方为滑车神经出脑处；脑桥臂（小脑中脚）有三叉神经根连出"},{"q":"面神经的连脑部位为","o":["延髓脑桥沟","脚间窝","前外侧沟","脑桥臂","中脑背面"],"a":0,"e":"面神经根连于延髓脑桥沟，沟内自中线向外侧依次连展神经、面神经、前庭蜗神经根。脚间窝为动眼神经出脑处；前外侧沟为舌下神经根丝出脑处；脑桥臂（小脑中脚）连三叉神经根；中脑下丘下方为滑车神经出脑处"},{"q":"三叉神经的连脑部位为","o":["延髓脑桥沟","脚间窝","前外侧沟","脑桥臂","中脑背面"],"a":3,"e":"三叉神经根（粗大感觉根和细小运动根）连于脑桥基底部与小脑中脚（脑桥臂）交界处。展神经、面神经、前庭蜗神经连于延髓脑桥沟；动眼神经自脚间窝出脑；舌下神经经前外侧沟出脑；滑车神经自中脑下丘下方出脑"},{"q":"支配眼球外肌运动的是","o":["面神经","舌神经","动眼神经","眼神经","视神经"],"a":2,"e":"动眼神经含一般躯体运动纤维，起自中脑动眼神经核，支配上直肌、下直肌、内直肌、下斜肌和上睑提肌。滑车神经支配上斜肌、展神经支配外直肌；眼神经仅含躯体感觉纤维、分布于眼球和泪器；面神经支配表情肌；视神经传导视觉"},{"q":"支配舌前2/3一般感觉的是","o":["面神经","舌神经","动眼神经","眼神经","视神经"],"a":1,"e":"舌神经为下颌神经的分支，含一般躯体感觉纤维，分布于口腔底和舌前2/3黏膜，传导一般感觉；其行程中接受面神经鼓索加入，鼓索的味觉纤维司舌前2/3味觉。面神经本身不司舌前2/3一般感觉；眼神经分布于眼区；动眼神经、视神经与舌无关"},{"q":"支配表情肌运动的是","o":["面神经","舌神经","动眼神经","眼神经","视神经"],"a":0,"e":"面神经含特殊内脏运动纤维，起自脑桥面神经核，支配全部表情肌及二腹肌后腹、茎突舌骨肌、镫骨肌。三叉神经支配咀嚼肌；动眼神经支配眼球外肌和眼内肌；眼神经为感觉神经、分布于眼区；视神经传导视觉"},{"q":"传导视觉信息的是","o":["面神经","舌神经","动眼神经","眼神经","视神经"],"a":4,"e":"视神经为特殊躯体感觉纤维，由视网膜节细胞轴突在视神经盘汇集、穿巩膜筛板形成，向后内行经视神经管入颅，传导视觉信息。动眼神经支配眼球外肌及瞳孔括约肌、睫状肌；眼神经传导眼部一般感觉；面神经、舌神经与视觉传导无关"},{"q":"支配角膜感觉的是","o":["面神经","舌神经","动眼神经","眼神经","视神经"],"a":3,"e":"眼神经（三叉神经第一支）仅含躯体感觉纤维，经眶上裂入眶，分布于眼球、角膜、结膜、泪器及额顶部皮肤，传导角膜感觉。动眼神经支配眼外肌和眼内肌运动；视神经传导视觉；面神经支配表情肌并含泪腺分泌纤维；舌神经分布于舌前2/3"},{"q":"参与大脑-小脑环路形成的是","o":["顶核","球状核","栓状核","齿状核","红核"],"a":3,"e":"齿状核为新小脑（大脑小脑）的传出核，接受小脑皮质梨状细胞轴突，发出纤维经小脑上脚止于对侧红核和背侧丘脑腹前核、腹外侧核，后者投射至大脑皮质运动区，再经皮质脑桥束、脑桥核和小脑中脚返回小脑，构成大脑-小脑环路。顶核属原小脑；球状核、栓状核合称中间核、属旧小脑；红核为中脑核团"},{"q":"属于原小脑的是","o":["顶核","球状核","栓状核","齿状核","红核"],"a":0,"e":"顶核位于第四脑室顶的上方、小脑蚓的白质内，属原小脑（前庭小脑），其传出纤维经顶核延髓束至前庭神经核和网状结构，调节躯干肌运动与平衡。齿状核最大、位于小脑半球白质内，属新小脑；球状核、栓状核合称中间核、属旧小脑；红核位于中脑、不属小脑"},{"q":"位于第四脑室顶的上方的是","o":["顶核","球状核","栓状核","齿状核","红核"],"a":0,"e":"顶核位于第四脑室顶的上方、小脑蚓的白质内，属原小脑。齿状核位于小脑半球白质内、体积最大，呈皱缩口袋状、袋口朝前内侧，属新小脑；球状核、栓状核位于顶核与齿状核之间、合称中间核，属旧小脑；红核位于中脑被盖、不在此处"},{"q":"不属于小脑核的是","o":["顶核","球状核","栓状核","齿状核","红核"],"a":4,"e":"小脑核由内侧向外侧依次为顶核、球状核、栓状核和齿状核，共4对；球状核与栓状核合称中间核、属旧小脑，顶核属原小脑，齿状核属新小脑。红核位于中脑被盖，是小脑上传导路的靶核并发出红核脊髓束，不属于小脑核"},{"q":"迷走神经支配","o":["腮腺","舌下腺","前列腺","尿道球腺","胃腺"],"a":4,"e":"迷走神经含一般内脏运动纤维，起自迷走神经背核，分布至颈部、胸腔和腹腔大部分脏器，其节后纤维支配平滑肌、心肌和腺体，故支配胃腺分泌。腮腺由舌咽神经经耳神经节支配；舌下腺由面神经经下颌下神经节支配；前列腺和尿道球腺由盆内脏神经支配"},{"q":"面神经支配","o":["腮腺","舌下腺","前列腺","尿道球腺","胃腺"],"a":1,"e":"面神经的副交感纤维经下颌下神经节换元后，支配下颌下腺和舌下腺的分泌。腮腺由舌咽神经经耳神经节支配；胃腺受迷走神经支配；前列腺和尿道球腺由骶髓S2至S4的盆内脏神经支配，均不属面神经分布区"},{"q":"舌咽神经支配","o":["腮腺","舌下腺","前列腺","尿道球腺","胃腺"],"a":0,"e":"舌咽神经含一般内脏运动纤维，起自下泌涎核，在耳神经节换元后，节后纤维经耳颞神经的腮腺支支配腮腺分泌。舌下腺由面神经经下颌下神经节支配；胃腺由迷走神经支配；前列腺和尿道球腺由盆内脏神经支配"},{"q":"喉与气管杈之间的通气管道是","o":["气管","主支气管","肺叶支气管","支气管","肺段支气管"],"a":0,"e":"气管位于喉与气管杈之间，成年男性平均长约10.31cm、女性约9.71cm，由气管软骨环作支架。主支气管为气管杈至肺门之间的通气管道；肺叶支气管在肺门处由主支气管分出、进入肺叶；肺段支气管为肺叶支气管再分出的三级支气管"},{"q":"第一肺门至第二肺门之间的通气管道是","o":["气管","主支气管","肺叶支气管","支气管","肺段支气管"],"a":2,"e":"主支气管在肺门（第一肺门）处分出二级支气管进入肺叶，称肺叶支气管，走行于第一、第二肺门之间，左肺有上、下叶支气管，右肺有上、中、下叶支气管。主支气管为气管杈至肺门的一段；肺段支气管为肺叶支气管入肺叶后再分出的三级支气管"},{"q":"气管杈至肺泡管之间的通气管道是","o":["气管","主支气管","肺叶支气管","支气管","肺段支气管"],"a":3,"e":"支气管为气管分出的各级分支，自气管杈起反复分支直达肺泡管，共23～25级，形如树状称支气管树。主支气管仅为气管杈至肺门的一级分支；肺叶支气管、肺段支气管为其下级分支，分布范围均不及支气管完整"},{"q":"气管杈与第一肺门之间的通气管道是","o":["气管","主支气管","肺叶支气管","支气管","肺段支气管"],"a":1,"e":"主支气管（左、右主支气管）为气管杈与第一肺门（肺门）之间的通气管道，是支气管的第一级分支，右主支气管较粗短、左主支气管较细长。气管位于喉与气管杈之间；肺叶支气管自肺门分出进入肺叶；肺段支气管为更细的分支"},{"q":"空肠和回肠的副交感神经来源于","o":["喉上神经","喉返神经","胃前支","肝支","腹腔支"],"a":4,"e":"腹腔支为迷走神经后干的分支，与交感神经在腹腔干、肠系膜上动脉和肾动脉根部形成神经丛，随动脉分布于结肠左曲以上的消化管，包括空肠、回肠。喉上神经分布声门裂以上喉黏膜；喉返神经支配喉肌及声门下黏膜；肝支随肝固有动脉分布肝和胆囊；胃前支分布胃前壁"},{"q":"传导声门裂以上喉黏膜感觉的是","o":["喉上神经","喉返神经","胃前支","肝支","腹腔支"],"a":0,"e":"喉上神经内支与喉上动脉伴行，穿甲状舌骨膜入喉，分布于声门裂以上的喉黏膜及会厌、舌根，传导一般内脏感觉。喉返神经支配除环甲肌外的喉肌并传导声门裂以下黏膜感觉；喉上神经外支为运动纤维、支配环甲肌；胃前支、肝支、腹腔支为迷走神经腹腔内分支"},{"q":"发自迷走神经后干的分支是","o":["喉上神经","喉返神经","胃前支","肝支","腹腔支"],"a":4,"e":"迷走神经后干入腹腔后分为胃后支和腹腔支，腹腔支是后干的主要分支，参与组成腹腔丛并随动脉分布。胃前支和肝支均发自迷走神经前干；喉上神经、喉返神经为迷走神经颈部的分支，均非后干发出"},{"q":"由腹横筋膜形成的是","o":["精索内筋膜","精索外筋膜","提睾肌","肉膜","睾丸鞘膜"],"a":0,"e":"精索内筋膜为腹横筋膜的延续，是包被精索和睾丸的最内层被膜。精索外筋膜为腹外斜肌腱膜的延续；提睾肌来自腹内斜肌和腹横肌的肌纤维束；肉膜为阴囊的浅筋膜、参与形成阴囊中隔；睾丸鞘膜来自腹膜，分壁、脏两层"},{"q":"由腹内斜肌和腹横肌共同形成的是","o":["精索内筋膜","精索外筋膜","提睾肌","肉膜","睾丸鞘膜"],"a":2,"e":"提睾肌由腹内斜肌最下部和腹横肌最下部的肌纤维束共同包绕精索和睾丸而成，可反射性上提睾丸。精索内筋膜为腹横筋膜的延续；精索外筋膜为腹外斜肌腱膜的延续；肉膜为阴囊浅筋膜；睾丸鞘膜来自腹膜"},{"q":"形成阴囊中隔的是","o":["精索内筋膜","精索外筋膜","提睾肌","肉膜","睾丸鞘膜"],"a":3,"e":"肉膜为阴囊的浅筋膜，含平滑肌纤维，随温度变化舒缩以调节阴囊温度；它在阴囊缝处向深部发出阴囊中隔，将阴囊分为左右两腔。精索内筋膜为腹横筋膜延续；精索外筋膜为腹外斜肌腱膜延续；提睾肌来自腹内斜肌和腹横肌；睾丸鞘膜来自腹膜"},{"q":"阴囊的浅筋膜又称为","o":["精索内筋膜","精索外筋膜","提睾肌","肉膜","睾丸鞘膜"],"a":3,"e":"阴囊壁由皮肤和肉膜组成，肉膜即阴囊的浅筋膜，与腹前壁Scarpa筋膜和会阴Colles筋膜相延续，内含平滑肌纤维、可调节阴囊温度。精索内筋膜为腹横筋膜延续；精索外筋膜为腹外斜肌腱膜延续；提睾肌来自腹内斜肌、腹横肌；睾丸鞘膜来自腹膜"},{"q":"会厌谷位于","o":["鼻咽部","口咽部","喉咽部","咽鼓管咽口","食管"],"a":1,"e":"会厌谷为舌会厌正中襞两侧的深窝，位于口咽部，是异物易停留处。鼻咽位于鼻腔后方，侧壁有咽鼓管咽口和咽隐窝；喉咽位于会厌上缘以下至食管入口；咽鼓管咽口经咽鼓管通中耳鼓室；食管为消化管"},{"q":"梨状隐窝位于","o":["鼻咽部","口咽部","喉咽部","咽鼓管咽口","食管"],"a":2,"e":"梨状隐窝位于喉咽部，在喉口两侧、甲状软骨板内侧与杓状软骨之间，是异物易滞留处。鼻咽部的隐窝为咽隐窝，是鼻咽癌好发部位；口咽部有腭扁桃体窝，固有口腔属口腔本部，均不含梨状隐窝"},{"q":"咽隐窝位于","o":["鼻咽部","口咽部","喉咽部","咽鼓管咽口","食管"],"a":0,"e":"咽隐窝为咽鼓管圆枕后方与咽后壁之间的纵行深窝，位于鼻咽部，是鼻咽癌的好发部位。会厌谷位于口咽部舌会厌正中襞两侧；喉咽为会厌以下至食管入口的一段；咽鼓管咽口位于鼻咽侧壁、通中耳鼓室；食管为消化管"},{"q":"与中耳鼓室相通的是","o":["鼻咽部","口咽部","喉咽部","咽鼓管咽口","食管"],"a":3,"e":"咽鼓管咽口位于鼻咽侧壁、下鼻甲后方约1cm处，咽腔经咽鼓管与中耳鼓室相通，吞咽或张口时开放以平衡鼓膜两侧气压。咽隐窝在咽鼓管圆枕后方，为鼻咽癌好发处；口咽、喉咽为消化与呼吸的共同通道；食管为消化管"},{"q":"食管的第2处狭窄距中切牙约","o":["15cm","25cm","35cm","40cm","75cm"],"a":1,"e":"食管第2狭窄位于左主支气管后方与其交叉处，相当于第4、5胸椎椎体之间水平，距中切牙约25cm，是异物滞留和食管癌好发部位。第1狭窄在食管起始处、平第6颈椎下缘，距中切牙约15cm；第3狭窄在穿膈食管裂孔处、平第10胸椎，距中切牙约40cm；十二指肠大乳头距中切牙约75cm"},{"q":"十二指肠大乳头距中切牙约","o":["15cm","25cm","35cm","40cm","75cm"],"a":4,"e":"十二指肠大乳头为十二指肠降部后内侧壁纵襞下端的圆形隆起，是肝胰壶腹的开口处，距中切牙约75cm；其上方约1～2cm处有时有十二指肠小乳头、为副胰管开口。食管三处狭窄分别距中切牙约15cm、25cm、40cm"},{"q":"食管的第一处狭窄距中切牙约","o":["15cm","25cm","35cm","40cm","75cm"],"a":0,"e":"食管第1狭窄为食管起始处，相当于第6颈椎椎体下缘水平，距中切牙约15cm。第2狭窄在左主支气管后方交叉处、平第4、5胸椎之间，距中切牙约25cm；第3狭窄在穿膈食管裂孔处、平第10胸椎，距中切牙约40cm；十二指肠大乳头距中切牙约75cm"},{"q":"食管长约","o":["15cm","25cm","35cm","40cm","75cm"],"a":1,"e":"食管为前后扁平的肌性管状器官，是消化管各部中最狭窄的部分，长约25cm，上端于第6颈椎下缘接咽，下端约平第11胸椎高度接胃贲门。食管三处狭窄距中切牙分别约15cm、25cm、40cm；十二指肠大乳头距中切牙约75cm"},{"q":"食管的第3处狭窄距中切牙约","o":["15cm","25cm","35cm","40cm","75cm"],"a":3,"e":"食管第3狭窄为食管通过膈的食管裂孔处，相当于第10胸椎水平，距中切牙约40cm，是异物易滞留和食管癌好发部位。第1狭窄在食管起始处、距中切牙约15cm；第2狭窄在左主支气管后方交叉处、距中切牙约25cm；十二指肠大乳头距中切牙约75cm"},{"q":"脊髓表面最深的沟裂是","o":["前正中裂","后外侧沟","前外侧沟","后中间沟","后正中沟"],"a":0,"e":"前正中裂位于脊髓前面正中，平均深约3mm，是脊髓表面最深的沟裂，有脊髓前动脉沿其下行。后正中沟较浅；后中间沟为薄束与楔束在脊髓表面的分界；前、后外侧沟分别为脊神经前、后根根丝附着处，均较浅"},{"q":"薄束核楔束在脊髓表面的分界","o":["前正中裂","后外侧沟","前外侧沟","后中间沟","后正中沟"],"a":3,"e":"在颈髓和上部胸髓，后正中沟与后外侧沟之间有后中间沟，将后索分为内侧薄束和外侧楔束，是二者在脊髓表面的分界标志。后正中沟为后索正中的浅沟；后外侧沟有脊神经后根附着；前外侧沟有前根附着；前正中裂最深"},{"q":"脊神经后根附着于","o":["前正中裂","后外侧沟","前外侧沟","后中间沟","后正中沟"],"a":1,"e":"脊神经后根由感觉性神经根丝构成，附着于脊髓后外侧沟。前根由运动性根丝构成，附着于前外侧沟，二者在椎间孔处合成脊神经；前正中裂为脊髓前动脉走行处、最深；后正中沟为后索正中的浅沟；后中间沟为薄束楔束分界"},{"q":"脊神经前根附着于","o":["前正中裂","后外侧沟","前外侧沟","后中间沟","后正中沟"],"a":2,"e":"脊神经前根由运动性神经根丝构成，附着于脊髓前外侧沟，与后根在椎间孔处合成混合性脊神经。后外侧沟有感觉性的后根附着；前正中裂最深、有脊髓前动脉下行；后正中沟居后索正中；后中间沟为薄束与楔束的分界标志"},{"q":"左肾上腺静脉注入","o":["肝静脉","腰升静脉","左肾静脉","肝门静脉","右肾静脉"],"a":2,"e":"左肾上腺静脉注入左肾静脉，右肾上腺静脉则直接注入下腔静脉，左肾静脉还接受左睾丸静脉或左卵巢静脉。肝静脉注入下腔静脉；腰升静脉向上续为半奇静脉或奇静脉；肝门静脉收集腹腔不成对脏器的静脉血入肝；右肾静脉较短，不接纳左侧的肾上腺静脉"},{"q":"左睾丸静脉注入","o":["肝静脉","腰升静脉","左肾静脉","肝门静脉","右肾静脉"],"a":2,"e":"左睾丸静脉以直角注入左肾静脉，右侧以锐角注入下腔静脉，左侧回流受阻是精索静脉曲张多见于左侧的原因。肝静脉注入下腔静脉；腰升静脉向上续为奇静脉或半奇静脉；肝门静脉收集腹腔不成对脏器的静脉血；右肾静脉注入下腔静脉，并不接纳右侧睾丸静脉"},{"q":"左腰静脉注入","o":["肝静脉","腰升静脉","左肾静脉","肝门静脉","右肾静脉"],"a":1,"e":"各腰静脉之间的纵支连成腰升静脉，左腰静脉注入左腰升静脉，左腰升静脉向上续为半奇静脉，向下与髂总静脉和髂腰静脉交通。肝静脉注入下腔静脉；左肾静脉接受左睾丸静脉和左肾上腺静脉；肝门静脉收集腹腔不成对脏器静脉血；右肾静脉注入下腔静脉"},{"q":"奇静脉注入哪条静脉","o":["气管静脉","食管静脉","右腰升静脉","骶外侧静脉","上腔静脉"],"a":4,"e":"奇静脉在右膈脚处起自右腰升静脉，沿食管后方和胸主动脉右侧上行，至第4胸椎高度向前勾绕右肺根上方注入上腔静脉，是沟通上、下腔静脉系的重要通道。气管静脉和食管静脉为奇静脉的属支而非其注入处；右腰升静脉是奇静脉的起始来源；骶外侧静脉注入髂总静脉"},{"q":"脊柱静脉注入哪条静脉","o":["气管静脉","食管静脉","右腰升静脉","骶外侧静脉","上腔静脉"],"a":3,"e":"椎内、外静脉丛无瓣膜且互相吻合，注入邻近的椎静脉、肋间后静脉、腰静脉和骶外侧静脉等。气管静脉和食管静脉主要汇入奇静脉系；右腰升静脉向上续为奇静脉；上腔静脉由左、右头臂静脉汇合而成并接纳奇静脉，均非脊柱静脉的主要注入处"},{"q":"半奇静脉接受哪条静脉","o":["气管静脉","食管静脉","右腰升静脉","骶外侧静脉","上腔静脉"],"a":1,"e":"半奇静脉收集左侧下部肋间后静脉、食管静脉和副半奇静脉的血液，约在第8胸椎高度向右跨过脊柱注入奇静脉。气管静脉汇入奇静脉等；右腰升静脉向上续为奇静脉而非注入半奇静脉；骶外侧静脉注入髂总静脉；上腔静脉接纳奇静脉，不是半奇静脉的属支"},{"q":"胃的出口是","o":["胃底","贲门","幽门部","幽门","角切迹"],"a":3,"e":"幽门是胃的出口，为胃远端接续十二指肠处，表面有幽门前静脉横过作为手术标志，幽门括约肌可延缓排空并防止肠内容物逆流。贲门为胃的入口；幽门部是胃体下界至幽门之间的区域，并非出口本身；胃底为贲门平面以上膨出部；角切迹为胃小弯最低点折转处"},{"q":"临床称为胃穹隆的是","o":["胃底","贲门","幽门部","幽门","角切迹"],"a":0,"e":"胃底为贲门平面以上向左上方膨出的部分，临床称胃穹窿，内含吞咽进入的空气约50ml，X线片可见气泡。贲门是胃的入口；幽门为出口；幽门部临床称胃窦；角切迹是胃小弯最低点弯度明显折转处，均与胃穹窿不同"},{"q":"胃小弯最低点的折转处是","o":["胃底","贲门","幽门部","幽门","角切迹"],"a":4,"e":"角切迹为胃小弯最低点弯度明显折转处，是胃体与幽门部分界的标志。胃底为贲门平面以上的膨出部；贲门为入口；幽门部为胃体下界至幽门之间部分；幽门为胃的出口并接续十二指肠，位置约在第1腰椎右侧"},{"q":"临床称为胃窦的是","o":["胃底","贲门","幽门部","幽门","角切迹"],"a":2,"e":"幽门部为胃体下界与幽门之间的部分，临床称胃窦，其中间沟将其分为幽门管和幽门窦，胃溃疡与胃癌多见于幽门窦近胃小弯处。胃底临床称胃穹窿；贲门为胃的入口；幽门为出口；角切迹为胃小弯最低点的折转处"},{"q":"十二指肠下动脉起自","o":["腹腔干","肝总动脉","脾动脉","肠系膜上动脉","胃十二指肠动脉"],"a":3,"e":"胰十二指肠下动脉（题称十二指肠下动脉）起自肠系膜上动脉，行于胰头与十二指肠之间，分前、后支与胰十二指肠上动脉吻合，营养胰和十二指肠。胰十二指肠上动脉起自胃十二指肠动脉；腹腔干分胃左、肝总、脾动脉；胃十二指肠动脉为肝总动脉分支"},{"q":"胃短动脉起自","o":["腹腔干","肝总动脉","脾动脉","肠系膜上动脉","胃十二指肠动脉"],"a":2,"e":"胃短动脉起自脾动脉末端或其分支，经胃脾韧带至胃底，供应胃底前后面。胃左动脉起自腹腔干、胃右动脉起自肝固有动脉，二者沿胃小弯；胃网膜左动脉起自脾动脉、胃网膜右动脉起自胃十二指肠动脉，二者沿胃大弯；肠系膜上动脉供应中肠"},{"q":"行于隔缘肉柱内的是","o":["窦房结","房室结","房室束","左束支","右束支"],"a":4,"e":"右束支起自房室束分叉部末端，沿室间隔右侧面下行进入隔缘肉柱，到达右心室前乳头肌根部，右心室手术时应避免损伤隔缘肉柱以免发生右束支传导阻滞。窦房结位于上腔静脉与右心房交界处；房室结位于Koch三角尖端；房室束穿右纤维三角；左束支行于室间隔左侧心内膜下"},{"q":"位于Koch三角深面的是","o":["窦房结","房室结","房室束","左束支","右束支"],"a":1,"e":"房室结为房室交界区的中央部分，位于Koch三角的尖端深面，是兴奋从心房传向心室的必经之路和重要的次级起搏点。窦房结位于上腔静脉与右心房交界处心外膜下；房室束起自房室结前端并穿右纤维三角；左、右束支为房室束的分支，分别行于室间隔两侧"},{"q":"又称His束的是","o":["窦房结","房室结","房室束","左束支","右束支"],"a":2,"e":"房室束又称His束，起自房室结前端，穿右纤维三角，行于室间隔膜部后下缘，末端分为左、右束支，是心房与心室间兴奋传导的唯一通道。窦房结为正常起搏点；房室结位于Koch三角尖端，为次级起搏点；左束支和右束支均为房室束的分支"},{"q":"关于肛门内括约肌正确的是","o":["如被切断，可导致肛门失禁","为肠壁环层肌增厚而成","分为皮下部、浅部和深部","参与构成盆膈","参与构成尿生殖膈"],"a":1,"e":"肛门内括约肌由肠壁环行肌增厚形成，为平滑肌管，环绕肛管上3/4段，自肛管直肠交界延伸至白线，仅协助排便、无括约肛门作用。切断致失禁、分皮下部浅部深部均为肛门外括约肌的特点；该肌为骨骼肌；盆膈、尿生殖膈由肛提肌、会阴深横肌等构成"},{"q":"关于肛直肠环正确的是","o":["如被切断，可导致肛门失禁","为肠壁环层肌增厚而成","分为皮下部、浅部和深部","参与构成盆膈","参与构成尿生殖膈"],"a":0,"e":"肛直肠环由肛门外括约肌浅部和深部、直肠下份纵行肌、肛门内括约肌及肛提肌等共同构成，围绕肛管、有极重要的括约作用，手术损伤将导致大便失禁。肠壁环行肌增厚而成的是肛门内括约肌；分皮下部、浅部和深部是肛门外括约肌的分部；盆膈、尿生殖膈为盆底结构"},{"q":"关于肛门外括约肌正确的是","o":["如被切断，可导致肛门失禁","为肠壁环层肌增厚而成","分为皮下部、浅部和深部","参与构成盆膈","参与构成尿生殖膈"],"a":2,"e":"肛门外括约肌为骨骼肌管，围绕整个肛管、受意识支配，按纤维所在部位分为皮下部、浅部和深部，其中浅、深部是控制排便的重要肌束。切断致失禁主要描述肛直肠环损伤，其皮下部切断并不失禁；肠壁环行肌增厚而成是肛门内括约肌；盆膈由肛提肌等构成；尿生殖膈由会阴深横肌等构成"},{"q":"经梨状肌上孔出盆腔到达臀部的神经是","o":["坐骨神经","股神经","闭孔神经","腓总神经","臀上神经"],"a":4,"e":"臀上神经由骶丛发出，伴臀上血管经梨状肌上孔出盆腔至臀部，行于臀中、小肌之间并支配之。坐骨神经多经梨状肌下孔出盆腔；股神经来自腰丛，经腹股沟韧带深面入股三角；闭孔神经经闭孔出盆腔；腓总神经在腘窝由坐骨神经发出"},{"q":"腓骨颈处骨折易损伤的神经是","o":["坐骨神经","股神经","闭孔神经","腓总神经","臀上神经"],"a":3,"e":"腓总神经在腓骨颈处位置最表浅，绕腓骨颈向前穿过腓骨长肌，骨折易受损，伤后足不能背屈、趾不能伸，足下垂内翻呈马蹄内翻足并有小腿前外侧及足背感觉障碍。坐骨神经在股后区；股神经支配股前群；闭孔神经支配股内侧群；臀上神经支配臀中、小肌"},{"q":"受伤后会导致膝跳反射消失的神经是","o":["坐骨神经","股神经","闭孔神经","腓总神经","臀上神经"],"a":1,"e":"股神经支配股四头肌，受损后屈髋无力、坐位时不能伸膝、行走困难、膝跳反射消失，伴大腿前面和小腿内侧面感觉障碍。坐骨神经支配大腿后群；闭孔神经支配大腿内侧群；腓总神经支配小腿前外侧群，损伤致足下垂；臀上神经支配臀中、小肌"},{"q":"支配大腿肌后群的神经是","o":["坐骨神经","股神经","闭孔神经","腓总神经","臀上神经"],"a":0,"e":"坐骨神经在股后区发出肌支支配股二头肌、半腱肌和半膜肌，即大腿肌后群。股神经支配缝匠肌和股四头肌等前群；闭孔神经支配长收肌、股薄肌等内侧群；腓总神经支配小腿前外侧群；臀上神经支配臀中、小肌"},{"q":"支配长收肌的神经是","o":["坐骨神经","股神经","闭孔神经","腓总神经","臀上神经"],"a":2,"e":"闭孔神经肌支支配闭孔外肌、长收肌、短收肌、大收肌和股薄肌等大腿内侧群肌，皮支分布于大腿内侧皮肤。坐骨神经支配大腿后群；股神经支配股四头肌、缝匠肌等前群；腓总神经支配小腿前外侧群；臀上神经支配臀中、小肌"},{"q":"支配大腿前群肌的是","o":["坐骨神经","股神经","闭孔神经","腓总神经","臀上神经"],"a":1,"e":"股神经为腰丛最大分支，支配大腿前群的缝匠肌和股四头肌，受损后屈髋无力、不能伸膝、膝跳反射消失。坐骨神经支配大腿后群；闭孔神经支配内侧群；腓总神经支配小腿前外侧群；臀上神经支配臀中、小肌并有血管伴行经梨状肌上孔"},{"q":"髂骨、耻骨和坐骨共同形成的结构是","o":["坐骨大切迹","坐骨小切迹","闭孔","髋臼","耻骨嵴"],"a":3,"e":"髋臼由髂骨体、坐骨体和耻骨体三骨会合而成，约16岁完全融合，窝内有半月形关节面称月状面。闭孔由耻骨与坐骨共同围成；坐骨大切迹位于髂后下棘下方；坐骨小切迹位于坐骨棘下方；耻骨嵴为耻骨上支上面的锐嵴"},{"q":"耻骨与坐骨共同形成的结构是","o":["坐骨大切迹","坐骨小切迹","闭孔","髋臼","耻骨嵴"],"a":2,"e":"闭孔由耻骨与坐骨共同围成，活体有闭孔膜封闭，孔上缘有闭孔沟，有闭孔神经和血管通过。髋臼由髂、坐、耻三骨的体共同合成；坐骨大切迹在髂后下棘下方；坐骨小切迹在坐骨棘下方；耻骨嵴为耻骨上支的锐嵴"},{"q":"髂骨形成的结构是","o":["坐骨大切迹","坐骨小切迹","闭孔","髋臼","耻骨嵴"],"a":0,"e":"坐骨大切迹位于髂后下棘下方，由髂骨形成，与骶棘韧带围成坐骨大孔。坐骨小切迹在坐骨棘下方，属坐骨；闭孔由耻骨与坐骨围成；髋臼由髂、坐、耻三骨共同构成；耻骨嵴为耻骨上支的锐嵴，均非髂骨单独形成"},{"q":"坐骨形成的结构是","o":["坐骨大切迹","坐骨小切迹","闭孔","髋臼","耻骨嵴"],"a":1,"e":"坐骨小切迹位于坐骨棘下方，由坐骨形成，与骶棘韧带、骶结节韧带围成坐骨小孔。坐骨大切迹在髂后下棘下方，属髂骨；闭孔由耻骨与坐骨围成；髋臼由髂、坐、耻三骨共同构成；耻骨嵴为耻骨上支的锐嵴"},{"q":"发出节后纤维支配舌下腺的是","o":["睫状神经节","翼腭神经节","耳神经节","下颌下神经节","三叉神经节"],"a":3,"e":"下颌下神经节为颅部副交感神经节，位于舌神经下方，面神经鼓索的副交感节前纤维在此换元，节后纤维支配下颌下腺和舌下腺分泌。翼腭神经节节后纤维至泪腺及鼻腔、腭黏膜腺；耳神经节经耳颞神经支配腮腺；睫状神经节支配瞳孔括约肌和睫状肌；三叉神经节为感觉节"},{"q":"发出节后纤维支配腮腺的是","o":["睫状神经节","翼腭神经节","耳神经节","下颌下神经节","三叉神经节"],"a":2,"e":"耳神经节位于卵圆孔下方、下颌神经内侧，舌咽神经下泌涎核发出的节前纤维经岩小神经至此换元，节后纤维经耳颞神经支配腮腺分泌。下颌下神经节支配下颌下腺和舌下腺；翼腭神经节支配泪腺及鼻、腭黏膜腺；睫状神经节支配瞳孔括约肌、睫状肌；三叉神经节为感觉节"},{"q":"发出节后纤维支配泪腺的是","o":["睫状神经节","翼腭神经节","耳神经节","下颌下神经节","三叉神经节"],"a":1,"e":"翼腭神经节位于翼腭窝内，面神经岩大神经的副交感节前纤维在此换元，节后纤维分布至泪腺及鼻腔、腭黏膜腺。下颌下神经节支配下颌下腺、舌下腺；耳神经节支配腮腺；睫状神经节支配瞳孔括约肌和睫状肌；三叉神经节为感觉神经节"},{"q":"发出节后纤维支配下颌下腺的是","o":["睫状神经节","翼腭神经节","耳神经节","下颌下神经节","三叉神经节"],"a":3,"e":"下颌下神经节位于下颌下腺深面、舌神经下方，面神经鼓索的副交感节前纤维经舌神经至此换元，节后纤维支配下颌下腺和舌下腺。翼腭神经节支配泪腺和鼻、腭黏膜腺；耳神经节支配腮腺；睫状神经节支配瞳孔括约肌、睫状肌；三叉神经节为感觉节"},{"q":"发出节后纤维支配瞳孔括约肌的是","o":["睫状神经节","翼腭神经节","耳神经节","下颌下神经节","三叉神经节"],"a":0,"e":"睫状神经节为副交感神经节，位于视神经与外直肌之间，动眼神经副核的节前纤维经睫状神经节短根至此换元，节后纤维支配瞳孔括约肌和睫状肌，参与对光和调节反射。翼腭神经节支配泪腺；耳神经节支配腮腺；下颌下神经节支配下颌下腺、舌下腺；三叉神经节为感觉节"},{"q":"由中央前回中上部和中央旁小叶前半部的锥体细胞发出的轴突","o":["皮质脊髓束","皮质核束","皮质脑桥束","顶盖脊髓束","下运动神经元"],"a":0,"e":"皮质脊髓束由中央前回上、中部和中央旁小叶前半部的锥体细胞轴突组成，下行经内囊后肢、大脑脚底外侧部和脑桥基底部至延髓锥体，主要支配肢体肌。皮质核束起自中央前回下部，支配脑神经运动核；皮质脑桥束终于脑桥核；顶盖脊髓束起自上丘；下运动神经元指脊髓前角细胞等"},{"q":"支配动眼神经核的纤维束","o":["皮质脊髓束","皮质核束","皮质脑桥束","顶盖脊髓束","下运动神经元"],"a":1,"e":"皮质核束主要起自中央前回下部锥体细胞，经内囊膝下行，大部分终止于双侧脑神经运动核，动眼神经核即接受双侧皮质核束支配。皮质脊髓束下行终于脊髓前角运动核；皮质脑桥束止于脑桥核；顶盖脊髓束起自上丘，参与视听反射；下运动神经元指脑神经运动核和脊髓前角细胞及其轴突"},{"q":"对侧睑裂以下的面肌和对侧舌肌均瘫痪，可能损伤","o":["皮质脊髓束","皮质核束","皮质脑桥束","顶盖脊髓束","下运动神经元"],"a":1,"e":"支配面神经核下部即睑裂以下面肌和舌下神经核的皮质核束纤维只接受对侧支配，故皮质核束损伤出现对侧面下部肌和对侧舌肌的核上瘫。皮质脊髓束损伤致对侧肢体痉挛性瘫痪；皮质脑桥束参与共济运动；顶盖脊髓束司视听反射；下运动神经元损伤表现为同侧全侧面肌或全舌肌核下瘫"},{"q":"肢体肌瘫痪，肌张力降低，并出现肌萎缩，可能损伤","o":["皮质脊髓束","皮质核束","皮质脑桥束","顶盖脊髓束","下运动神经元"],"a":4,"e":"下运动神经元损伤指脑神经运动核、脊髓前角细胞及其轴突受损，表现为随意运动障碍、肌张力降低的弛缓性瘫痪、明显肌萎缩、深反射减弱或消失且无病理反射。皮质脊髓束等上运动神经元损伤则为硬瘫，肌张力增高、腱反射亢进、早期肌萎缩不明显并可出现Babinski征"},{"q":"上、下肢肌痉挛性瘫痪，而躯干肌不受影响，可能损伤","o":["皮质脊髓束","皮质核束","皮质脑桥束","顶盖脊髓束","下运动神经元"],"a":0,"e":"支配上、下肢肌的前角运动神经元只接受对侧大脑皮质支配，支配躯干肌的接受双侧支配，故一侧皮质脊髓束损伤致损伤平面以下同侧上、下肢痉挛性瘫痪而躯干肌不受累。皮质核束支配脑神经运动核；皮质脑桥束止于脑桥核；顶盖脊髓束与视听反射有关；下运动神经元损伤为弛缓性瘫并伴肌萎缩"},{"q":"供应室间隔后1/3部的动脉是","o":["左冠状动脉旋支","左冠状动脉前室间支","右冠状动脉主干","右冠状动脉后室间支","右冠状动脉左心室后支"],"a":3,"e":"后室间支沿后室间沟下行，发出7～12支室间隔后支穿入室间隔，供应室间隔后1/3，是其主要供血动脉。前室间支供应室间隔前2/3及左心室前壁；旋支主要供应左心室侧壁；右冠状动脉主干多走行于冠状沟，不直接穿入室间隔"},{"q":"引起左心室侧壁心肌梗死的动脉是","o":["左冠状动脉旋支","左冠状动脉前室间支","右冠状动脉主干","右冠状动脉后室间支","右冠状动脉左心室后支"],"a":0,"e":"旋支由左冠状动脉主干发出后行于左侧冠状沟，绕心左缘至左心室膈面，主要供应左心室侧壁，闭塞即致侧壁心肌梗死。前室间支供应左心室前壁及室间隔前2/3；后室间支供应室间隔后1/3及心室下壁；右冠状动脉主干一般不供应左心室侧壁"},{"q":"左心室前壁和室间隔前部心肌梗死由哪个动脉分支闭塞所致的是","o":["左冠状动脉旋支","左冠状动脉前室间支","右冠状动脉主干","右冠状动脉后室间支","右冠状动脉左心室后支"],"a":1,"e":"前室间支（前降支）为左冠状动脉的直接延续，沿前室间沟下行，发室间隔前支供应室间隔前2/3，并发出对角支供应左心室前壁，闭塞致前壁及室间隔前部梗死。旋支主要供应侧壁；后室间支供应室间隔后1/3；右冠状动脉主干多分布于右心"},{"q":"房室结（动脉）支一般起自","o":["左冠状动脉旋支","左冠状动脉前室间支","右冠状动脉主干","右冠状动脉后室间支","右冠状动脉左心室后支"],"a":2,"e":"房室结动脉一般在房室交点附近起自右冠状动脉主干，供应房室结，属右优势型的常见配置。左冠状动脉旋支主要供应左心室侧壁，一般不发房室结支；后室间支主要供应室间隔后1/3；仅在左优势型时房室结动脉才起自左冠状动脉，但属少数情况"},{"q":"支配舌骨舌肌的是","o":["迷走神经","三叉神经","动眼神经","面神经","舌下神经"],"a":4,"e":"舌下神经支配舌内肌和大部分舌外肌（如颏舌肌、茎突舌肌、舌骨舌肌），一侧完全损伤时患侧半舌肌瘫痪、伸舌时舌尖偏向患侧。迷走神经支配喉肌和大部分胸腹腔脏器；三叉神经支配咀嚼肌；动眼神经支配眼球外肌；面神经支配表情肌"},{"q":"支配咀嚼肌的是","o":["迷走神经","三叉神经","动眼神经","面神经","舌下神经"],"a":1,"e":"三叉神经运动根起自脑桥三叉神经运动核，并入下颌神经经卵圆孔出颅，支配咀嚼肌（咬肌、颞肌、翼内肌、翼外肌）、二腹肌前腹、下颌舌骨肌、腭帆张肌和鼓膜张肌。迷走神经支配喉肌和内脏；动眼神经支配眼球外肌；面神经支配表情肌；舌下神经支配舌肌"},{"q":"支配镫骨肌的是","o":["迷走神经","三叉神经","动眼神经","面神经","舌下神经"],"a":3,"e":"镫骨肌位于鼓室锥隆起内，为鼓膜张肌的拮抗肌，收缩时解除鼓膜紧张状态，由面神经的镫骨肌神经支配。鼓膜张肌由三叉神经下颌神经支配；迷走神经支配喉肌；动眼神经支配眼球外肌；舌下神经支配舌肌"},{"q":"支配喉肌的是","o":["迷走神经","三叉神经","动眼神经","面神经","舌下神经"],"a":0,"e":"迷走神经的喉返神经支配除环甲肌以外的全部喉肌，环甲肌由喉上神经外支支配，二者均属迷走神经。三叉神经支配咀嚼肌；动眼神经支配眼球外肌；面神经支配表情肌；舌下神经支配舌肌"},{"q":"支配颞肌的是","o":["迷走神经","三叉神经","动眼神经","面神经","舌下神经"],"a":1,"e":"颞肌为咀嚼肌之一，由三叉神经下颌神经的颞深神经支配，起自颞窝、止于下颌骨冠突，收缩时上提下颌骨。咬肌、翼内肌、翼外肌也由下颌神经支配；迷走神经支配喉肌；面神经支配表情肌；舌下神经支配舌肌；动眼神经支配眼球外肌"},{"q":"动眼神经副核属于","o":["一般躯体运动核","一般内脏运动核","特殊内脏运动核","一般躯体感觉核","特殊躯体感觉核"],"a":1,"e":"动眼神经副核（E-W核）位于中脑上丘高度、动眼神经核背内侧，属一般内脏运动核（副交感核），发出节前纤维随动眼神经至睫状神经节换元，支配瞳孔括约肌和睫状肌。一般躯体运动核包括动眼、滑车、展、舌下神经核；特殊内脏运动核支配咀嚼肌、面肌；感觉性核团为感觉性"},{"q":"面神经核属于","o":["一般躯体运动核","一般内脏运动核","特殊内脏运动核","一般躯体感觉核","特殊躯体感觉核"],"a":2,"e":"面神经核位于脑桥下部被盖腹外侧，属特殊内脏运动核，发出纤维支配表情肌、二腹肌后腹、茎突舌骨肌和镫骨肌（均由鳃弓衍化）。一般躯体运动核（动眼、滑车、展、舌下神经核）支配肌节衍化的眼外肌和舌肌；一般内脏运动核为副交感核；一般、特殊躯体感觉核均为感觉性"},{"q":"前庭蜗神经核属于","o":["一般躯体运动核","一般内脏运动核","特殊内脏运动核","一般躯体感觉核","特殊躯体感觉核"],"a":4,"e":"前庭蜗神经核（前庭神经核和蜗神经核）属特殊躯体感觉核，分别接受内耳的平衡觉和听觉纤维；因内耳膜迷路起源于外胚层，听觉和平衡觉归入躯体感觉。一般躯体运动核、特殊内脏运动核、一般内脏运动核均为运动性；一般躯体感觉核接受一般躯体感觉纤维，与特殊感觉不同"},{"q":"下泌涎核属于","o":["一般躯体运动核","一般内脏运动核","特殊内脏运动核","一般躯体感觉核","特殊躯体感觉核"],"a":1,"e":"下泌涎核位于延髓上部，属一般内脏运动核（副交感核），发出节前纤维经舌咽神经鼓室神经、岩小神经至耳神经节换元，支配腮腺分泌。一般内脏运动核还包括动眼神经副核、上泌涎核、迷走神经背核；一般躯体运动核支配眼外肌、舌肌；特殊内脏运动核支配鳃弓肌；感觉核为感觉性"},{"q":"患者脑损伤后，虽能说话，但患者无法正确表述和回答问题，损伤的部位是","o":["Broca区","书写区","听觉性语言区","视觉性语言区","第1听区"],"a":2,"e":"听觉性语言区在颞上回后部22区，能调整自身语言并理解他人讲话，受损后虽能听到声音但不解其意，自己讲话混乱割裂，不能正确回答问题，称感觉性失语症。Broca区受损为运动性失语，能发音却说不出有意义语言；书写区受损致失写症；视觉性语言区受损致失读症"},{"q":"接受内侧膝状体来的纤维位于","o":["Broca区","书写区","听觉性语言区","视觉性语言区","第1听区"],"a":4,"e":"第1听区位于颞横回41、42区，接受内侧膝状体传入的纤维，每侧均接受两耳冲动，一侧受损不引起全聋。Broca区为运动性语言区；书写区在额中回后部；听觉性语言区在颞上回后部，司语言理解；视觉性语言区在角回，为阅读中枢"},{"q":"患者脑损伤后，视觉无障碍，但无法阅读原先认识的文字，也不理解文字符号的意义，损伤的部位是","o":["Broca区","书写区","听觉性语言区","视觉性语言区","第1听区"],"a":3,"e":"视觉性语言区又称阅读中枢，在顶下小叶角回39区，受损后视觉无障碍却不能阅读原来认识的文字，也不理解文字符号的意义，称失读症。听觉性语言区受损为感觉性失语，听不懂他人讲话；书写区受损致失写症，手运动存在而不能写字绘图；第1听区受损不致全聋"},{"q":"某患者脑损伤后，虽能发音，却说不出具有意义的语言，损伤的部位是","o":["Broca区","书写区","听觉性语言区","视觉性语言区","第1听区"],"a":0,"e":"Broca区即运动性语言区，位于额下回后1/3的44、45区，受损后患者虽能发音却说不出具有意义的语言，称运动性失语症。书写区受损致失写症；听觉性语言区受损为感觉性失语，言语混乱且理解障碍；视觉性语言区受损致失读症"},{"q":"肾门约平对","o":["第11胸椎体下缘","第12胸椎体上缘","第1腰椎体平面","第2～3腰椎椎间盘","第3腰椎体上缘"],"a":2,"e":"肾门约平第1腰椎椎体平面，相当于第9肋软骨前端高度，距后正中线约5cm，是肾窦的开口、有肾血管和肾盂等出入。第11胸椎体下缘为左肾上端；第12胸椎体上缘为右肾上端；第2～3腰椎椎间盘为左肾下端；第3腰椎体上缘为右肾下端"},{"q":"右肾下端平对","o":["第11胸椎体下缘","第12胸椎体上缘","第1腰椎体平面","第2～3腰椎椎间盘","第3腰椎体上缘"],"a":4,"e":"右肾因受肝右叶影响位置较左肾低约半个椎体，位于第12胸椎体上缘至第3腰椎体上缘之间，故下端平第3腰椎体上缘。左肾下端平第2～3腰椎椎间盘；左肾上端平第11胸椎体下缘；右肾上端平第12胸椎体上缘；肾门平第1腰椎体平面"},{"q":"左肾上端平对","o":["第11胸椎体下缘","第12胸椎体上缘","第1腰椎体平面","第2～3腰椎椎间盘","第3腰椎体上缘"],"a":0,"e":"左肾位于第11胸椎椎体下缘至第2～3腰椎椎间盘之间，上端平第11胸椎体下缘，位置较右肾高约半个椎体。右肾上端平第12胸椎体上缘；右肾下端平第3腰椎体上缘；左肾下端平第2～3腰椎椎间盘；肾门平第1腰椎体平面"},{"q":"右肾上端平对","o":["第11胸椎体下缘","第12胸椎体上缘","第1腰椎体平面","第2～3腰椎椎间盘","第3腰椎体上缘"],"a":1,"e":"右肾受肝右叶影响位置较左肾低约半个椎体，上端平第12胸椎体上缘，下端平第3腰椎体上缘。左肾上端平第11胸椎体下缘；左肾下端平第2～3腰椎椎间盘；肾门平第1腰椎体平面、约当第9肋软骨前端高度"},{"q":"左肾下端平对","o":["第11胸椎体下缘","第12胸椎体上缘","第1腰椎体平面","第2～3腰椎椎间盘","第3腰椎体上缘"],"a":3,"e":"左肾位于第11胸椎椎体下缘至第2～3腰椎椎间盘之间，下端平第2～3腰椎椎间盘。右肾下端平第3腰椎体上缘；左肾上端平第11胸椎体下缘；右肾上端平第12胸椎体上缘；肾门平第1腰椎体平面"},{"q":"组成骶丛的是L4～L5，S1～S5，C0神经的","o":["前支","后支","前根","后根","交通支"],"a":0,"e":"骶丛由腰骶干和全部骶、尾神经的前支组成，腰骶干由第4腰神经前支部分纤维与第5腰神经前支全部纤维合成，故为前支。后支主要分布于项、背、腰骶部深层肌和皮肤；前根为运动性、后根为感觉性，二者在椎间孔合成脊神经；交通支连接交感干与脊神经"},{"q":"含有运动性纤维成分的结构是","o":["前支","后支","前根","后根","交通支"],"a":2,"e":"前根连于脊髓前外侧沟，由运动性神经根丝构成，含躯体运动和内脏运动纤维，是典型的运动性结构。后根由感觉性根丝构成，传导各类感觉；前支和后支均为前、后根合成的混合性神经；交通支主要含交感的节前或节后纤维"},{"q":"含有感觉性纤维成分的结构是","o":["前支","后支","前根","后根","交通支"],"a":3,"e":"后根连于脊髓后外侧沟，由感觉性神经根丝构成，传导痛温觉、本体感觉及触压觉等，是感觉性纤维成分的结构。前根为运动性；前支、后支由前、后根合成，为混合性；交通支主要含交感神经纤维"},{"q":"分布于项部、背部和腰骶部的神经分支是","o":["前支","后支","前根","后根","交通支"],"a":1,"e":"脊神经后支为混合性，向躯干背面走行，分布于项、背、腰、骶、臀部的深层肌和皮肤，具明显节段性。前支组成颈丛、腰丛、骶丛，分布于四肢及躯干前外侧面；前根为运动性、后根为感觉性；交通支连于交感干与脊神经之间"},{"q":"仅含有交感神经纤维的是","o":["前支","后支","前根","后根","交通支"],"a":4,"e":"交通支连于交感干与脊神经前支之间，白交通支为交感节前纤维、灰交通支为交感节后纤维，仅含交感神经纤维。前支、后支为混合性，兼含感觉与运动纤维；前根含躯体运动及交感节前纤维；后根为感觉性"},{"q":"听觉传导通路的第3级神经元胞体位于","o":["外侧膝状体","内侧膝状体","下丘","蜗神经","听辐射"],"a":2,"e":"听觉传导通路第1级神经元为蜗神经节细胞，第2级在蜗腹侧核和蜗背侧核，其纤维大部分交叉形成外侧丘系并止于下丘核，第3级神经元胞体在下丘，纤维经下丘臂止于内侧膝状体，第4级在内侧膝状体发出听辐射。外侧膝状体为视觉中继站；蜗神经为第1级纤维；听辐射为第4级纤维"},{"q":"行经内囊后肢的结构是","o":["外侧膝状体","内侧膝状体","下丘","蜗神经","听辐射"],"a":4,"e":"听辐射由内侧膝状体发出，经内囊后肢（豆状核下部）投射至颞横回听区；视辐射、皮质脊髓束和丘脑中央辐射也经内囊后肢。外侧膝状体、内侧膝状体、下丘为中继核团，位于内囊之外；蜗神经为周围神经、不入内囊。本题选项中仅听辐射为经内囊后肢的纤维束"},{"q":"视觉传导通路的第3级神经元胞体位于","o":["外侧膝状体","内侧膝状体","下丘","蜗神经","听辐射"],"a":0,"e":"视觉传导通路第1级为视网膜双极细胞，第2级为节细胞，其轴突组成视束主要终止于外侧膝状体，第3级神经元胞体在外侧膝状体，发出视辐射经内囊后肢投射至视区皮质。内侧膝状体为听觉中继站；下丘为听觉反射中枢；蜗神经、听辐射均属听觉通路"},{"q":"患者一侧听觉出现明显障碍可能的受损部位是","o":["外侧膝状体","内侧膝状体","下丘","蜗神经","听辐射"],"a":3,"e":"听觉冲动在脑干为双侧传导，外侧丘系以上一侧受损不产生明显症状；而损伤蜗神经、内耳或中耳则导致单侧明显听觉障碍。外侧膝状体为视觉中继核；内侧膝状体、下丘为听觉通路中继，一侧损伤因双侧传导症状不明显；听辐射一侧损伤亦无明显听力障碍"},{"q":"右冠状动脉主干走行于","o":["冠状沟","前室间沟","后室间沟","界沟","房间沟"],"a":0,"e":"右冠状动脉起自主动脉右窦，行于右心耳与肺动脉干之间，沿冠状沟右行、绕心锐缘至膈面冠状沟，在房室交点附近分为后室间支和右旋支。前室间沟内有左冠状动脉前室间支和心大静脉；后室间沟有后室间支和心中静脉；界沟为右心房的分界；房间沟为左右心房分界"},{"q":"心中静脉走行于","o":["冠状沟","前室间沟","后室间沟","界沟","房间沟"],"a":2,"e":"心中静脉起自心尖，伴右冠状动脉后室间支上行于后室间沟，注入冠状窦右端，收纳左右心室后壁、室间隔后部及心尖部的静脉血。心大静脉伴前室间支走行于前室间沟；心小静脉在冠状沟内伴右冠状动脉；冠状沟内有冠状窦主干；房间沟为左右心房的分界"},{"q":"心房与心室的表面分界标志是","o":["冠状沟","前室间沟","后室间沟","界沟","房间沟"],"a":0,"e":"冠状沟（房室沟）几乎呈额状位、近似环形，前方被肺动脉干中断，是右上方心房与左下方心室在心表面的分界。前、后室间沟是左右心室在心表面的分界；界沟为右心房内、外面的分界；后房间沟为左右心房在心表面的分界"},{"q":"心大静脉走行于","o":["冠状沟","前室间沟","后室间沟","界沟","房间沟"],"a":1,"e":"心大静脉起自心尖，在前室间沟伴左冠状动脉前室间支上行，斜向左上进入冠状沟，绕心左缘至膈面，于左房斜静脉注入处移行为冠状窦。心中静脉伴后室间支走行于后室间沟；心小静脉在冠状沟内伴右冠状动脉；冠状沟为房室分界；房间沟为心房分界"},{"q":"使瞳孔转向内上方的为","o":["上直肌","下斜肌","内直肌","上斜肌","外直肌"],"a":0,"e":"上直肌收缩使瞳孔转向内上方；下直肌转向内下方，内直肌转向内侧，外直肌转向外侧；上斜肌使瞳孔转向下外方，下斜肌转向上外方。本题选项中，下斜肌使瞳孔转向上外方而非内上；内直肌仅内转；外直肌外转；上斜肌使之下外转"},{"q":"受展神经支配的是","o":["上直肌","下斜肌","内直肌","上斜肌","外直肌"],"a":4,"e":"展神经支配外直肌，使其收缩时瞳孔转向外侧，损伤后同侧眼球不能外展、出现内斜视。上直肌、内直肌、下斜肌均由动眼神经支配；上斜肌由滑车神经支配；眼神经、视神经为感觉神经，与眼球运动无关"},{"q":"使瞳孔转向下外方的是","o":["上直肌","下斜肌","内直肌","上斜肌","外直肌"],"a":3,"e":"上斜肌起于蝶骨体，以细腱经眶内侧壁前上方的滑车转折后向外，止于眼球赤道后方的巩膜，收缩使瞳孔转向下外方，由滑车神经支配。下斜肌使瞳孔转向上外方；上直肌转向内上方；内直肌转向内侧；外直肌转向外侧"},{"q":"起自眶下壁的为","o":["上直肌","下斜肌","内直肌","上斜肌","外直肌"],"a":1,"e":"下斜肌位于眶下壁与下直肌之间，起自眶下壁的前内侧，斜向后外止于眼球下面赤道后方的巩膜，收缩使瞳孔转向上外方。上直肌、内直肌、外直肌均起自视神经管周围的总腱环；上斜肌起于蝶骨体并经滑车转折"},{"q":"感受头部静止位置刺激的是","o":["壶腹嵴","椭圆囊斑和球囊斑","螺旋器","血管纹","基底膜"],"a":1,"e":"椭圆囊斑和球囊斑位于椭圆囊和球囊内，属位置觉感受器，感受头部静止的位置及直线变速运动引起的刺激，冲动沿前庭神经的椭圆囊支、球囊支传入。壶腹嵴位于膜半规管壶腹部、感受旋转变速运动刺激；螺旋器为听觉感受器；血管纹产生内淋巴；基底膜为蜗管底壁、载螺旋器"},{"q":"直线加速或减速运动时刺激的结构是","o":["壶腹嵴","椭圆囊斑和球囊斑","螺旋器","血管纹","基底膜"],"a":1,"e":"椭圆囊斑和球囊斑为位置觉感受器，感受头部静止位置及直线变速（加速或减速）运动引起的刺激。壶腹嵴感受旋转变速运动的刺激；螺旋器（Corti器）为听觉感受器、感受声波刺激；血管纹分泌内淋巴；基底膜为螺旋器的依托结构"},{"q":"听觉感受器是","o":["壶腹嵴","椭圆囊斑和球囊斑","螺旋器","血管纹","基底膜"],"a":2,"e":"螺旋器又称Corti器，位于蜗管鼓壁的螺旋膜上，是听觉感受器。壶腹嵴为感受头部旋转变速运动的位置觉感受器；椭圆囊斑和球囊斑感受直线变速运动及静止体位；血管纹与内淋巴的产生有关；基底膜为螺旋器的附着部位，本身不是感受器"},{"q":"头部旋转时刺激的结构是","o":["壶腹嵴","椭圆囊斑和球囊斑","螺旋器","血管纹","基底膜"],"a":0,"e":"壶腹嵴位于膜半规管膨大的膜壶腹内，为位置觉感受器，能感受头部旋转变速运动，三个壶腹嵴相互垂直以感受三维空间的运动变化。椭圆囊斑和球囊斑感受直线变速运动及静止体位；螺旋器感受声波。血管纹参与内淋巴生成，不感受运动刺激"},{"q":"产生内淋巴的结构是","o":["壶腹嵴","椭圆囊斑和球囊斑","螺旋器","血管纹","基底膜"],"a":3,"e":"血管纹为蜗管外侧壁骨膜的增厚部分，富有血管，一般认为与内淋巴的产生有关，其钠泵调节内淋巴电解质成分。螺旋器是听觉感受器；壶腹嵴、椭圆囊斑和球囊斑均为位置觉感受器；基底膜为螺旋器的附着处并参与声波传导，均不产生内淋巴"},{"q":"静脉韧带位于","o":["肝右纵沟前部","肝右纵沟后部","横沟","肝左纵沟前部","肝左纵沟后部"],"a":4,"e":"肝左纵沟后部为静脉韧带裂，容纳静脉韧带，由胎儿时期的静脉导管闭锁而成。肝右纵沟前部为胆囊窝、容纳胆囊；右纵沟后部为腔静脉沟、容纳下腔静脉；横沟为肝门（第一肝门），有肝管、肝固有动脉、肝门静脉等出入；左纵沟前部为肝圆韧带裂、容纳肝圆韧带"},{"q":"肝门位于","o":["肝右纵沟前部","肝右纵沟后部","横沟","肝左纵沟前部","肝左纵沟后部"],"a":2,"e":"肝门（第一肝门）位于肝脏面中部的横沟处，有肝左、右管，肝固有动脉左、右支，肝门静脉左、右支及神经、淋巴管出入，这些结构被结缔组织包绕称肝蒂。左纵沟前部容纳肝圆韧带、后部容纳静脉韧带；右纵沟前部为胆囊窝、后部为腔静脉沟（其上端为第二肝门）"},{"q":"下腔静脉位于","o":["肝右纵沟前部","肝右纵沟后部","横沟","肝左纵沟前部","肝左纵沟后部"],"a":1,"e":"肝右纵沟后部为腔静脉沟，容纳下腔静脉，沟向后上伸入膈面，其上端处肝左、中、右静脉出肝后注入下腔静脉、称第二肝门。右纵沟前部为胆囊窝、容纳胆囊；横沟为肝门；左纵沟前部为肝圆韧带裂、后部为静脉韧带裂"},{"q":"胆囊位于","o":["肝右纵沟前部","肝右纵沟后部","横沟","肝左纵沟前部","肝左纵沟后部"],"a":0,"e":"肝右纵沟前部为胆囊窝，容纳胆囊。右纵沟后部为腔静脉沟、容纳下腔静脉；横沟为肝门（第一肝门）；左纵沟前部为肝圆韧带裂、容纳肝圆韧带；左纵沟后部为静脉韧带裂、容纳静脉韧带"},{"q":"肝圆韧带位于","o":["肝右纵沟前部","肝右纵沟后部","横沟","肝左纵沟前部","肝左纵沟后部"],"a":3,"e":"肝左纵沟前部为肝圆韧带裂，容纳肝圆韧带，由胎儿时期脐静脉闭锁而成，经镰状韧带游离缘内行至脐。左纵沟后部为静脉韧带裂、容纳静脉韧带；右纵沟前部为胆囊窝；后部为腔静脉沟；横沟为肝门"},{"q":"尿液进入膀胱通过的结构是","o":["乳头孔","肾盂","输尿管口","尿道内口","尿道外口"],"a":2,"e":"输尿管口为输尿管末端开口于膀胱底的部位，尿液由此进入膀胱，两口之间的输尿管间襞是寻找输尿管口的标志。乳头孔为终尿从肾乳头流入肾小盏的开口；肾盂移行为输尿管；尿道内口为膀胱出口；尿道外口为尿液排出体外处"},{"q":"尿液离开膀胱通过的结构是","o":["乳头孔","肾盂","输尿管口","尿道内口","尿道外口"],"a":3,"e":"尿道内口为膀胱的出口，尿液由此离开膀胱进入尿道，也是尿道的三个狭窄之一。输尿管口为尿液进入膀胱处；乳头孔为肾乳头开口；肾盂为肾窦内移行为输尿管的结构；尿道外口是尿液排出体外的最终开口，位于阴茎头"},{"q":"输送尿液出肾的结构是","o":["乳头孔","肾盂","输尿管口","尿道内口","尿道外口"],"a":1,"e":"肾盂为肾门处肾窦内的漏斗状结构，约平第2腰椎上缘逐渐变细移行为输尿管，负责输送尿液出肾，成人容积约3～10ml。乳头孔为终尿流入肾小盏的开口；输尿管口开口于膀胱；尿道内口为膀胱出口；尿道外口为排尿通道的末端"},{"q":"尿液流入肾小盏通过的结构是","o":["乳头孔","肾盂","输尿管口","尿道内口","尿道外口"],"a":0,"e":"乳头孔为肾乳头顶端的小孔，肾生成的终尿经此流入肾小盏，每肾有7～12个肾乳头。肾盂为肾窦内移行为输尿管的结构；输尿管口开口于膀胱；尿道内口为膀胱出口；尿道外口为尿液排出体外处，均不在肾乳头"},{"q":"尿液离开人体通过的结构是","o":["乳头孔","肾盂","输尿管口","尿道内口","尿道外口"],"a":4,"e":"尿道外口为尿道末端的开口，是尿液排出体外的最后通道，也是尿道三个狭窄中最窄者，呈矢状裂隙。乳头孔为肾乳头排尿入肾小盏处；肾盂向下移行为输尿管；输尿管口为输尿管入膀胱处；尿道内口为膀胱的出口"},{"q":"穿视神经管的是","o":["眼神经","下颌神经","上颌神经","舌下神经","视神经"],"a":4,"e":"视神经由视网膜节细胞轴突汇集而成，向后内行经视神经管入颅中窝、移行为视交叉，管内尚有眼动脉伴行。眼神经经眶上裂入眶；上颌神经经圆孔出颅、再经眶下裂入眶；下颌神经经卵圆孔出颅；舌下神经经舌下神经管出颅"},{"q":"穿舌下神经管的是","o":["眼神经","下颌神经","上颌神经","舌下神经","视神经"],"a":3,"e":"舌下神经为运动性神经，起自延髓舌下神经核，经锥体与橄榄之间出脑，穿舌下神经管出颅，支配舌内、外肌。视神经穿视神经管；眼神经经眶上裂入眶；上颌神经经圆孔、眶下裂；下颌神经经卵圆孔出颅"},{"q":"穿卵圆孔的是","o":["眼神经","下颌神经","上颌神经","舌下神经","视神经"],"a":1,"e":"下颌神经为三叉神经第三支，含一般躯体感觉和特殊内脏运动纤维，经卵圆孔出颅，支配咀嚼肌等并管理下颌部感觉。眼神经经眶上裂入眶；上颌神经经圆孔出颅、眶下裂入眶；舌下神经经舌下神经管出颅；视神经经视神经管入颅"},{"q":"穿眶下裂的是","o":["眼神经","下颌神经","上颌神经","舌下神经","视神经"],"a":2,"e":"上颌神经为三叉神经第二支，经海绵窦外侧壁、穿圆孔出颅入翼腭窝，再向前经眶下裂入眶并改名为眶下神经，分布于下睑、鼻翼、上唇等处。眼神经经眶上裂入眶；下颌神经经卵圆孔出颅；舌下神经经舌下神经管；视神经经视神经管"},{"q":"穿圆孔的是","o":["眼神经","下颌神经","上颌神经","舌下神经","视神经"],"a":2,"e":"上颌神经含一般躯体感觉纤维，经海绵窦外侧壁穿圆孔出颅，进入翼腭窝上部，再经眶下裂入眶。眼神经经眶上裂入眶；下颌神经经卵圆孔出颅；舌下神经经舌下神经管出颅；视神经经视神经管入颅。圆孔与卵圆孔分别通行上颌、下颌神经，最易混淆"},{"q":"主要传导粗触觉、压觉信息的是","o":["薄束","楔束","脊髓丘脑前束","脊髓丘脑侧束","脊髓小脑束"],"a":2,"e":"脊髓丘脑前束位于前索，主要传递粗触觉和压觉信息，由脊髓灰质Ⅰ和Ⅳ至Ⅷ层发出纤维经白质前连合交叉至对侧前索上行。脊髓丘脑侧束位于外侧索，传递痛温觉；薄束和楔束传导意识性本体感觉和精细触觉；脊髓小脑束传导非意识性本体感觉至小脑"},{"q":"位于脊髓后索外侧部的是","o":["薄束","楔束","脊髓丘脑前束","脊髓丘脑侧束","脊髓小脑束"],"a":1,"e":"楔束起自同侧第4胸节及以上脊神经节细胞，在第4胸节以上位于后索的外侧部，传导上肢和躯干上部的意识性本体感觉和精细触觉。薄束起自第5胸节以下，居后索内侧部；脊髓丘脑前束位于前索；脊髓丘脑侧束位于外侧索；脊髓小脑束位于外侧索周边部"},{"q":"主要传导痛、温觉信息的是","o":["薄束","楔束","脊髓丘脑前束","脊髓丘脑侧束","脊髓小脑束"],"a":3,"e":"脊髓丘脑侧束位于外侧索前部，主要传递痛温觉信息，纤维经白质前连合交叉至对侧上行止于背侧丘脑。脊髓丘脑前束位于前索，传递粗触觉和压觉；薄束和楔束传导意识性本体感觉和精细触觉；脊髓小脑束将非意识性本体感觉传至小脑"},{"q":"起自同侧第5胸节以下的脊神经节细胞的是","o":["薄束","楔束","脊髓丘脑前束","脊髓丘脑侧束","脊髓小脑束"],"a":0,"e":"薄束起自同侧第5胸节及以下的脊神经节细胞，在后索内侧部上行止于薄束核，传导下肢和躯干下部的意识性本体感觉与精细触觉。楔束起自第4胸节及以上；脊髓丘脑前束和侧束起自脊髓灰质Ⅰ和Ⅳ至Ⅷ层；脊髓小脑束起自胸核或腰骶膨大Ⅴ至Ⅶ层"},{"q":"传导非意识性本体感觉和触、压觉信息的是","o":["薄束","楔束","脊髓丘脑前束","脊髓丘脑侧束","脊髓小脑束"],"a":4,"e":"脊髓小脑束包括前、后束及楔小脑束等，将躯干和下肢的非意识性本体感觉及触、压觉信息传至小脑，参与运动的协调。薄束和楔束传导意识性本体感觉和精细触觉至大脑皮质；脊髓丘脑前束传导粗触觉和压觉；脊髓丘脑侧束传导痛温觉"},{"q":"脑桥小脑束通过","o":["锥体","斜方体","小脑下脚","小脑中脚","小脑上脚"],"a":3,"e":"脑桥小脑束由对侧脑桥核发出的纤维横越中线组成小脑中脚进入小脑，是小脑中脚的主要成分。锥体为皮质脊髓束通过处；斜方体为听觉二级纤维的交叉通路；小脑下脚主要含脊髓小脑后束；小脑上脚主要含脊髓小脑前束"},{"q":"皮质脊髓束通过","o":["锥体","斜方体","小脑下脚","小脑中脚","小脑上脚"],"a":0,"e":"皮质脊髓束下行经内囊后肢、大脑脚底外侧部和脑桥基底部至延髓锥体，在锥体下端大部分纤维交叉形成锥体交叉。斜方体为听觉纤维交叉处；小脑中脚由脑桥小脑纤维组成；小脑上脚主要含脊髓小脑前束；小脑下脚主要含脊髓小脑后束"},{"q":"内侧丘系通过","o":["锥体","斜方体","小脑下脚","小脑中脚","小脑上脚"],"a":1,"e":"内侧丘系在脑桥穿经斜方体上行，其外侧有脊丘系和三叉丘系。斜方体由蜗神经核发出的听觉二级纤维在脑桥交叉形成并参与组成外侧丘系。锥体为皮质脊髓束下行处；小脑中脚由脑桥小脑纤维构成；小脑上、下脚为小脑与前庭、脊髓联系的纤维"},{"q":"脊髓小脑前束通过","o":["锥体","斜方体","小脑下脚","小脑中脚","小脑上脚"],"a":4,"e":"脊髓小脑前束起自腰骶膨大Ⅴ～Ⅶ层，大部分交叉后上行，经小脑上脚及前髓帆进入小脑皮质。脊髓小脑后束经小脑下脚进入；脑桥小脑束经小脑中脚进入；锥体为皮质脊髓束通过处；斜方体为听觉纤维交叉通路"},{"q":"脊髓小脑后束通过","o":["锥体","斜方体","小脑下脚","小脑中脚","小脑上脚"],"a":2,"e":"脊髓小脑后束起自同侧胸核，上行经小脑下脚终于小脑皮质，因胸核位于胸髓和上腰髓，故此束仅见于L2以上节段。脊髓小脑前束经小脑上脚；脑桥小脑束经小脑中脚；锥体为皮质脊髓束通过处；斜方体为听觉纤维交叉处"},{"q":"皮质核束通过","o":["锥体","斜方体","小脑下脚","小脑中脚","小脑上脚"],"a":0,"e":"皮质核束经内囊膝、大脑脚底中3/5内侧部下行，穿过脑桥基底部和延髓锥体，途中陆续终止于双侧脑神经运动核。皮质脊髓束也经锥体但下行入脊髓前角；斜方体为听觉交叉纤维；小脑中脚为脑桥小脑纤维；小脑上、下脚为小脑联系纤维"},{"q":"可使足背屈和内翻的肌是","o":["腓肠肌","胫骨前肌","胫骨后肌","腓骨长肌","比目鱼肌"],"a":1,"e":"胫骨前肌起自胫骨上端外侧面，止于内侧楔骨和第1跖骨底，作用为伸踝关节即背屈并使足内翻，由腓深神经支配。腓肠肌和比目鱼肌屈踝关节即跖屈而不背屈；胫骨后肌使足内翻但为跖屈；腓骨长肌跖屈并使足外翻"},{"q":"使足跖屈和内翻的肌是","o":["腓肠肌","胫骨前肌","胫骨后肌","腓骨长肌","比目鱼肌"],"a":2,"e":"胫骨后肌起自小腿骨间膜后面及胫、腓骨，止于足舟骨粗隆及楔骨，作用为使足内翻并协助屈踝关节即跖屈，由胫神经支配。胫骨前肌背屈并内翻；腓骨长肌跖屈但使足外翻；腓肠肌和比目鱼肌跖屈但不使足内翻"},{"q":"使足跖屈和外翻的肌是","o":["腓肠肌","胫骨前肌","胫骨后肌","腓骨长肌","比目鱼肌"],"a":3,"e":"腓骨长肌起自腓骨外侧面，肌腱经外踝后方转向前，止于内侧楔骨和第1跖骨底，作用为屈踝关节即跖屈并使足外翻，由腓浅神经支配。胫骨前肌背屈并内翻；胫骨后肌内翻并协助跖屈；腓肠肌和比目鱼肌跖屈但不使足外翻"},{"q":"伸肘关节和内收肩关节的肌是","o":["肱二头肌","肱三头肌","肱桡肌","三角肌","喙肱肌"],"a":1,"e":"肱三头肌位于臂后群，长头起自肩胛骨盂下结节，内侧头和外侧头起自肱骨桡神经沟附近，止于尺骨鹰嘴，作用为伸肘关节，长头并可协助肩关节后伸和内收。肱二头肌屈肘并屈肩；肱桡肌屈肘；三角肌外展肩关节；喙肱肌使肩关节屈和内收"},{"q":"屈肘关节并能屈肩关节的肌是","o":["肱二头肌","肱三头肌","肱桡肌","三角肌","喙肱肌"],"a":0,"e":"肱二头肌位于臂前群浅层，长头起自肩胛骨盂上结节，短头起自喙突，止于桡骨粗隆，作用为屈肘关节、屈肩关节并使前臂旋后。肱三头肌伸肘；肱桡肌屈肘但不屈肩；三角肌主要外展肩关节；喙肱肌屈和内收肩关节但不作用于肘关节"},{"q":"外展肩关节的主要肌是","o":["肱二头肌","肱三头肌","肱桡肌","三角肌","喙肱肌"],"a":3,"e":"三角肌位于肩部，起自锁骨外侧1/3、肩峰和肩胛冈，止于肱骨三角肌粗隆，是外展肩关节的主要肌，由腋神经支配，损伤后臂不能外展且肩部呈方肩。肱二头肌屈肘屈肩；肱三头肌伸肘；肱桡肌屈肘；喙肱肌屈和内收肩关节"},{"q":"属于节后纤维的是","o":["白交通支","灰交通支","交感干","椎前神经节","椎旁神经节"],"a":1,"e":"灰交通支为发自交感干椎旁神经节的无髓节后纤维，连于交感干与31对脊神经前支之间，因无髓鞘色灰暗而得名，分布于血管、汗腺和竖毛肌。白交通支由有髓的节前纤维构成，仅见于T1至L3节段；交感干为椎旁神经节借节间支相连；椎前和椎旁神经节为神经节而非纤维"},{"q":"属于节前纤维的是","o":["白交通支","灰交通支","交感干","椎前神经节","椎旁神经节"],"a":0,"e":"白交通支由脊髓T1至L3节段侧角发出的有髓节前纤维构成，因髓鞘折光而色泽白亮，进入交感干后终止于椎旁神经节或穿至椎前神经节换元。灰交通支为无髓节后纤维；交感干由椎旁神经节及节间支构成；椎前神经节和椎旁神经节为换元部位，本身不是纤维"},{"q":"主动脉肾神经节属于","o":["白交通支","灰交通支","交感干","椎前神经节","椎旁神经节"],"a":3,"e":"主动脉肾神经节位于脊柱前方、同名动脉根部附近，属椎前神经节，同类还有腹腔神经节和肠系膜上、下神经节。白交通支和灰交通支为交通支，分别含节前和节后纤维；交感干由椎旁神经节借节间支串联而成；椎旁神经节位于脊柱两旁，与椎前神经节位置不同"},{"q":"属于联络神经元的是","o":["假单极神经元","双极神经元","多极神经元","少突胶质细胞","小胶质细胞"],"a":2,"e":"联络神经元又称中间神经元，位于中枢部感觉神经元与运动神经元之间，属于多极神经元。假单极神经元和双极神经元属感觉神经元；少突胶质细胞为中枢神经系统形成髓鞘的胶质细胞；小胶质细胞来源于单核巨噬细胞，具吞噬功能，二者均非神经元"},{"q":"属于运动神经元的是","o":["假单极神经元","双极神经元","多极神经元","少突胶质细胞","小胶质细胞"],"a":2,"e":"运动神经元将冲动自中枢传向效应器，支配骨骼肌或管理心肌、平滑肌和腺体，属多极神经元，联络神经元也多为多极。假单极神经元和双极神经元为感觉神经元；少突胶质细胞形成中枢髓鞘；小胶质细胞为具有吞噬作用的胶质细胞，均不属运动神经元"},{"q":"形成神经纤维髓鞘的是","o":["假单极神经元","双极神经元","多极神经元","少突胶质细胞","小胶质细胞"],"a":3,"e":"中枢神经系统的髓鞘由少突胶质细胞形成，一个少突胶质细胞可形成多条轴突的髓鞘，周围神经系统的髓鞘则由施万细胞形成。假单极、双极和多极神经元均为神经元而非成髓鞘细胞；小胶质细胞来源于单核巨噬细胞，具吞噬功能，不形成髓鞘"},{"q":"接受听觉传入的是","o":["外侧膝状体","内侧膝状体","背侧丘脑外侧核群背层","腹中间核","腹后外侧核"],"a":1,"e":"内侧膝状体是听觉传导通路在丘脑的中继站，接受下丘来的听觉纤维，发出听辐射投射至颞叶听觉中枢。外侧膝状体为视觉中继站，接受视束传入并投射至枕叶视区；背侧丘脑外侧核群背层属新丘脑联络核；腹中间核参与运动调节；腹后外侧核接受内侧丘系和脊髓丘系"},{"q":"接受躯干、四肢躯体感觉传入的是","o":["外侧膝状体","内侧膝状体","背侧丘脑外侧核群背层","腹中间核","腹后外侧核"],"a":4,"e":"腹后外侧核接受内侧丘系和脊髓丘脑束的纤维，传导躯干四肢的意识性本体感觉、精细触觉及痛温觉，发出丘脑中央辐射投射至中央后回。内侧膝状体接受听觉传入；外侧膝状体接受视觉传入；背侧丘脑外侧核群背层为联络性核团；腹中间核接受小脑和纹状体传入参与运动调节"},{"q":"投射至大脑皮质视觉中枢的是","o":["外侧膝状体","内侧膝状体","背侧丘脑外侧核群背层","腹中间核","腹后外侧核"],"a":0,"e":"外侧膝状体为视觉传导通路的中继站，接受视束纤维，发出视辐射经内囊后肢投射至距状沟上下的视区皮质产生视觉。内侧膝状体为听觉中继站，投射至颞叶听区；背侧丘脑外侧核群背层属新丘脑；腹中间核与运动调节有关；腹后外侧核传导躯干四肢感觉至中央后回"},{"q":"小脑下脚主要含有","o":["前庭小脑纤维","脊髓小脑前束","脊髓小脑后束","脑桥小脑纤维","橄榄小脑纤维"],"a":2,"e":"小脑下脚主要含脊髓小脑后束，该束起自同侧胸核，上行经小脑下脚终于小脑皮质。脊髓小脑前束经小脑上脚入小脑；脑桥小脑纤维组成小脑中脚；前庭小脑纤维多经小脑下脚联系前庭神经核；橄榄小脑纤维亦经下脚进入，但本题所指主要成分为脊髓小脑后束"},{"q":"小脑上脚进入小脑的主要纤维束是","o":["前庭小脑纤维","脊髓小脑前束","脊髓小脑后束","脑桥小脑纤维","橄榄小脑纤维"],"a":1,"e":"脊髓小脑前束在脑桥上部经小脑上脚及前髓帆进入小脑皮质，是小脑上脚的主要传入纤维。脊髓小脑后束经小脑下脚；脑桥小脑纤维组成小脑中脚；前庭小脑纤维主要经小脑下脚；橄榄小脑纤维亦经小脑下脚进入小脑"},{"q":"经小脑中脚进入小脑的纤维束主要为","o":["前庭小脑纤维","脊髓小脑前束","脊髓小脑后束","脑桥小脑纤维","橄榄小脑纤维"],"a":3,"e":"小脑中脚又称脑桥臂，最粗大，几乎全部由对侧脑桥核发出的脑桥小脑纤维构成，将大脑皮质信息经脑桥核中继传入小脑。脊髓小脑前束经小脑上脚；脊髓小脑后束经小脑下脚；前庭小脑纤维主要经小脑下脚；橄榄小脑纤维亦由下脚进入"},{"q":"在肘关节，可防止桡骨头脱位的韧带是","o":["尺侧副韧带","桡侧副韧带","桡骨环状韧带","盂肱韧带","喙肱韧带"],"a":2,"e":"桡骨环状韧带位于桡骨环状关节面周围，两端附着于尺骨桡切迹的前、后缘，与桡切迹共同构成骨纤维环容纳桡骨头，防止其脱出，小儿桡骨头半脱位与此有关。尺侧副韧带位于关节囊内侧；桡侧副韧带位于外侧并加强关节囊；盂肱韧带和喙肱韧带为肩关节的韧带"},{"q":"在肘关节，位于关节囊外侧，并加强关节囊的韧带是","o":["尺侧副韧带","桡侧副韧带","桡骨环状韧带","盂肱韧带","喙肱韧带"],"a":1,"e":"桡侧副韧带位于肘关节囊的桡侧，由肱骨外上髁向下扩展止于桡骨环状韧带，加强关节囊外侧。尺侧副韧带位于关节囊尺侧即内侧；桡骨环状韧带环绕桡骨头以防止其脱出；盂肱韧带和喙肱韧带属于肩关节，与肘关节无关"},{"q":"在肘关节，位于关节囊内侧，并加强关节囊的韧带是","o":["尺侧副韧带","桡侧副韧带","桡骨环状韧带","盂肱韧带","喙肱韧带"],"a":0,"e":"尺侧副韧带位于肘关节囊的尺侧，由肱骨内上髁向下呈扇形扩展，止于尺骨滑车切迹内侧缘，加强关节囊内侧。桡侧副韧带位于关节囊外侧；桡骨环状韧带环绕桡骨头；盂肱韧带和喙肱韧带为肩关节的结构，不参与肘关节构成"},{"q":"食管淋巴管注入的是","o":["气管支气管淋巴结","肠系膜上淋巴结","纵隔前淋巴结","膈上淋巴结","右淋巴导管"],"a":0,"e":"食管胸部上部的淋巴注入气管旁淋巴结和气管支气管淋巴结，颈部注入气管旁及颈外侧下深淋巴结，胸下部和腹部注入胃左淋巴结，部分入胸导管。肠系膜上淋巴结收纳小肠等处淋巴；纵隔前淋巴结引流胸腺和心包等；膈上淋巴结引流膈和肝膈面；右淋巴导管为淋巴回流终点而非淋巴结群"},{"q":"肝淋巴管注入的是","o":["气管支气管淋巴结","肠系膜上淋巴结","纵隔前淋巴结","膈上淋巴结","右淋巴导管"],"a":3,"e":"肝膈面的浅淋巴管多经镰状韧带和冠状韧带注入膈上淋巴结和肝淋巴结，部分入腹腔淋巴结和胃左淋巴结，深淋巴管注入肝淋巴结、腹腔淋巴结和膈上淋巴结。气管支气管淋巴结引流肺和食管；肠系膜上淋巴结引流小肠；纵隔前淋巴结引流胸腺等；右淋巴导管为回流终末"},{"q":"肺淋巴管注入的是","o":["气管支气管淋巴结","肠系膜上淋巴结","纵隔前淋巴结","膈上淋巴结","右淋巴导管"],"a":0,"e":"肺的淋巴依次经肺淋巴结、支气管肺门淋巴结、气管支气管淋巴结和气管旁淋巴结引流，故注入气管支气管淋巴结。肠系膜上淋巴结引流小肠和结肠等；纵隔前淋巴结引流胸腺和心包前部；膈上淋巴结引流膈及肝膈面；右淋巴导管收纳右上肢、右半头颈和右胸部淋巴，为回流终点"},{"q":"内脏大神经主要终止于","o":["腹腔神经节","肠系膜上神经节","腰神经节","主动脉肾神经节","胸神经节"],"a":0,"e":"内脏大神经由第5或第6至第9胸交感干神经节的节前纤维组成，穿膈脚后终止于腹腔神经节和肠系膜上神经节。内脏小神经主要终止于主动脉肾神经节；腰内脏神经终于腹主动脉丛和肠系膜下丛内的椎前神经节；胸神经节发出节后纤维加入胸主动脉丛等；腰神经节位于腰椎体前外侧"},{"q":"内脏小神经主要终止于","o":["腹腔神经节","肠系膜上神经节","腰神经节","主动脉肾神经节","胸神经节"],"a":3,"e":"内脏小神经由第10至第12胸交感干神经节的节前纤维组成，下行穿膈脚，主要终止于主动脉肾神经节。内脏大神经主要终止于腹腔神经节和肠系膜上神经节；腰内脏神经终于腹主动脉丛和肠系膜下丛内椎前神经节；胸神经节和腰神经节均为交感干椎旁神经节"},{"q":"腰内脏神经主要穿过","o":["腹腔神经节","肠系膜上神经节","腰神经节","主动脉肾神经节","胸神经节"],"a":2,"e":"腰内脏神经由穿过腰交感干神经节即腰神经节的节前纤维组成，终止于腹主动脉丛和肠系膜下丛内的椎前神经节，节后纤维分布至结肠左曲以下消化管和盆腔脏器。腹腔神经节为内脏大神经主要终止处；主动脉肾神经节为内脏小神经主要终止处；肠系膜上神经节接受内脏大神经部分纤维"},{"q":"射精管开口于","o":["前列腺部","海绵体部","尿道球","尿道外口","尿道膜部"],"a":0,"e":"射精管由输精管末端与精囊排出管汇合而成，长约2cm，向前下穿前列腺实质，开口于尿道前列腺部后壁的精阜上。尿道球为尿道球腺开口处；海绵体部为前尿道；尿道外口最窄、呈矢状裂隙；尿道膜部为第二狭窄、有尿道括约肌环绕"},{"q":"尿道球腺开口于","o":["前列腺部","海绵体部","尿道球","尿道外口","尿道膜部"],"a":2,"e":"尿道球腺位于会阴深横肌内，其输出管开口于尿道球部（尿道球），分泌物参与精液组成、有利于精子活动。前列腺部有射精管和前列腺导管开口；海绵体部为尿道穿过尿道海绵体的部分；尿道外口最窄；尿道膜部有尿道括约肌环绕、为第二狭窄"},{"q":"男性尿道最狭窄的部位为","o":["前列腺部","海绵体部","尿道球","尿道外口","尿道膜部"],"a":3,"e":"男性尿道有三个狭窄（尿道内口、膜部、外口）、三个膨大（前列腺部、尿道球部、舟状窝）和两个弯曲（耻骨下弯、耻骨前弯），其中尿道外口最窄、呈矢状裂隙，是导尿和结石易嵌顿处。前列腺部、尿道球为膨大；膜部为第二狭窄但非最窄；海绵体部为前尿道"},{"q":"形成耻骨前弯的部位是","o":["前列腺部","海绵体部","尿道球","尿道外口","尿道膜部"],"a":1,"e":"耻骨前弯位于耻骨联合前下方，由尿道海绵体部（阴茎根与体之间）向上提起形成，上提阴茎时此弯可变直，便于导尿。耻骨下弯位于耻骨联合下方约2cm处，恒定不变，包括尿道前列腺部、膜部和海绵体部起始段；前列腺部、尿道膜部属耻骨下弯；尿道外口为最窄处"},{"q":"男性尿道的第二狭窄位于","o":["前列腺部","海绵体部","尿道球","尿道外口","尿道膜部"],"a":4,"e":"男性尿道三个狭窄依次为尿道内口（第一）、尿道膜部（第二）、尿道外口（第三且最窄），尿道膜部为尿道穿过尿生殖膈处，有尿道括约肌环绕、位置固定易损伤。前列腺部、尿道球为膨大；海绵体部为前尿道；尿道外口是最窄的第三狭窄"},{"q":"同时可见于左、右肺上叶的支气管肺段是","o":["前段","内侧段","上舌段","上段","外侧底段"],"a":0,"e":"通常左右肺各有10个支气管肺段，上叶均有尖段、后段和前段，故前段为左右肺上叶所共有。内侧段为右肺中叶的肺段；上舌段仅见于左肺上叶；上段为左右下叶的肺段，不在上叶；外侧底段为左右下叶共有的底段"},{"q":"仅属于右肺的支气管肺段是","o":["前段","内侧段","上舌段","上段","外侧底段"],"a":1,"e":"右肺中叶分为外侧段和内侧段，内侧段仅见于右肺。前段为左右肺上叶共有；上舌段为左肺上叶特有；上段为左右肺下叶共有；外侧底段亦为左右肺下叶共有的底段，均非右肺独有"},{"q":"仅属于左肺的支气管肺段是","o":["前段","内侧段","上舌段","上段","外侧底段"],"a":2,"e":"左肺上叶有上舌段和下舌段，为上舌段，属左肺特有。前段为左右肺上叶共有；内侧段为右肺中叶特有；上段和外侧底段均为左右肺下叶共有，均非左肺独有"},{"q":"胸廓内静脉注入","o":["腋静脉","锁骨下静脉","头臂静脉","上腔静脉","颈内静脉"],"a":2,"e":"胸廓内静脉伴胸廓内动脉，注入头臂静脉（无名静脉）。头臂静脉由颈内静脉与锁骨下静脉在胸锁关节后方汇合而成，还接受椎静脉、肋间最上静脉和甲状腺下静脉等；锁骨下静脉接受腋静脉和颈外静脉；上腔静脉由左右头臂静脉汇合"},{"q":"可使颊部贴紧牙齿，帮助咀嚼和吸吮的肌是","o":["枕额肌","翼内肌","眼轮匝肌","口轮匝肌","颊肌"],"a":4,"e":"颊肌位于面颊深层，起自面颊深层止于口角，收缩时使唇颊贴紧牙齿，帮助咀嚼和吸吮并牵拉口角向外侧，由面神经支配。枕额肌额腹提眉形成额纹、枕腹向后牵拉帽状腱膜；翼内肌为上提下颌骨的咀嚼肌；眼轮匝肌闭合眼裂；口轮匝肌闭合口裂"},{"q":"可扩大泪囊，以利泪液引流的肌是","o":["枕额肌","翼内肌","眼轮匝肌","口轮匝肌","颊肌"],"a":2,"e":"眼轮匝肌泪囊部收缩时牵引睑内侧韧带，扩大泪囊使囊内产生负压，促使泪液流入泪囊，其眶部和睑部纤维共同收缩可闭合眼裂。枕额肌作用于颅顶皮肤和眉；翼内肌为上提下颌骨的咀嚼肌；口轮匝肌闭合口裂；颊肌使唇颊贴紧牙齿帮助咀嚼和吸吮"},{"q":"可使额部皮肤出现皱纹的肌是","o":["枕额肌","翼内肌","眼轮匝肌","口轮匝肌","颊肌"],"a":0,"e":"枕额肌额腹位于额部皮下止于眉部皮肤，收缩时提眉并使额部皮肤出现皱纹，枕腹则向后牵拉帽状腱膜。翼内肌为上提下颌骨的咀嚼肌；眼轮匝肌闭合眼裂；口轮匝肌闭合口裂；颊肌使唇颊贴紧牙齿帮助咀嚼和吸吮，均不形成额纹"},{"q":"自子宫颈两侧缘达骨盆侧壁，固定子宫颈位置的主要韧带是","o":["子宫圆韧带","子宫阔韧带","子宫主韧带","骶子宫韧带","耻骨子宫韧带"],"a":2,"e":"子宫主韧带（又称子宫旁组织）由结缔组织和平滑肌构成，位于阔韧带基部，自子宫颈两侧缘延伸至盆侧壁，强韧，是固定子宫颈、防止子宫脱垂的主要结构。子宫圆韧带维持子宫前倾；阔韧带限制子宫向两侧移位；骶子宫韧带向后上牵引宫颈"},{"q":"维持子宫颈位于坐骨棘平面以上的主要结构是","o":["子宫圆韧带","子宫阔韧带","子宫主韧带","骶子宫韧带","耻骨子宫韧带"],"a":2,"e":"子宫主韧带自子宫颈两侧缘延伸到盆侧壁，承托并固定子宫颈，使其维持在坐骨棘平面以上，是防止脱垂的主要结构。子宫圆韧带向前牵引子宫体、维持前倾；阔韧带限制侧移；骶子宫韧带向后上牵引宫颈、协同维持前倾前屈位"},{"q":"限制子宫向两侧移动的韧带是","o":["子宫圆韧带","子宫阔韧带","子宫主韧带","骶子宫韧带","耻骨子宫韧带"],"a":1,"e":"子宫阔韧带是覆盖子宫前、后面的腹膜自子宫侧缘向两侧延伸形成的双层腹膜皱襞，可限制子宫向两侧移动。子宫圆韧带维持子宫前倾，子宫骶韧带牵引宫颈向后上，子宫主韧带防止子宫下垂，三者均不能限制侧方移动。卵巢悬韧带又名骨盆漏斗韧带，功能为悬吊卵巢"},{"q":"脐静脉闭锁形成的是","o":["脐正中襞","脐内侧襞","脐外侧襞","肝圆韧带","镰状韧带"],"a":3,"e":"肝圆韧带由胎儿时期的脐静脉闭锁而成，经镰状韧带的游离缘内行至脐，位于肝圆韧带裂内。脐正中襞内含脐尿管闭锁形成的脐正中韧带；脐内侧襞内含脐动脉闭锁形成的脐内侧韧带；脐外侧襞含腹壁下动静脉；镰状韧带为肝表面的腹膜皱襞"},{"q":"含有脐内侧韧带的是","o":["脐正中襞","脐内侧襞","脐外侧襞","肝圆韧带","镰状韧带"],"a":1,"e":"脐内侧襞位于脐正中襞的两侧，左右各一，内含脐动脉闭锁后形成的脐内侧韧带。脐正中襞内含脐尿管闭锁形成的脐正中韧带；脐外侧襞又称腹壁动脉襞，内含腹壁下动静脉；肝圆韧带为脐静脉闭锁的遗迹；镰状韧带为连接肝与膈及腹前壁的腹膜皱襞"},{"q":"含有腹壁下动、静脉的是","o":["脐正中襞","脐内侧襞","脐外侧襞","肝圆韧带","镰状韧带"],"a":2,"e":"脐外侧襞又称腹壁动脉襞，左右各一，位于脐内侧襞的外侧，内含腹壁下动脉和静脉，是腹前壁手术的重要标志。脐正中襞含脐正中韧带；脐内侧襞含脐动脉闭锁形成的脐内侧韧带；肝圆韧带为脐静脉闭锁形成；镰状韧带下缘内含肝圆韧带及附脐静脉"},{"q":"中枢神经系统是指","o":["端脑、间脑、小脑和脑干","脑和脊髓","脊神经和脑神经","脊髓和脑干","内脏神经"],"a":1,"e":"中枢神经系统由脑和脊髓组成，脑包括端脑、间脑、小脑和脑干。端脑、间脑、小脑和脑干仅为脑的分部，不含脊髓；脊神经和脑神经属周围神经系统；脊髓和脑干仅为中枢的一部分，遗漏端脑、间脑和小脑；内脏神经属周围神经"},{"q":"周围神经系统是指","o":["端脑、间脑、小脑和脑干","脑和脊髓","脊神经和脑神经","脊髓和脑干","内脏神经"],"a":2,"e":"周围神经系统指与脑相连的脑神经和与脊髓相连的脊神经，可再分为躯体神经和内脏神经。脑和脊髓属中枢神经系统；端脑、间脑、小脑和脑干为脑的分部，属中枢；脊髓和脑干属中枢的一部分；内脏神经只是周围神经按分布划分的一部分，不等同于周围神经系统整体"},{"q":"分布到内脏、心血管、平滑肌和腺体的是","o":["端脑、间脑、小脑和脑干","脑和脊髓","脊神经和脑神经","脊髓和脑干","内脏神经"],"a":4,"e":"内脏神经分布于内脏、心血管、平滑肌和腺体，其传出部分又称自主神经或植物神经，分为交感和副交感。端脑、间脑、小脑和脑干为中枢的分部；脑和脊髓为中枢神经系统；脊神经和脑神经中的躯体神经纤维主要分布于体表、骨、关节和骨骼肌；脊髓和脑干属中枢"},{"q":"由喙肩韧带与肩峰、喙突共同构成","o":["胸锁关节","肩关节","肩锁关节","喙肩弓","盂肱关节"],"a":3,"e":"喙肩韧带连于肩胛骨喙突与肩峰之间，与喙突、肩峰共同构成喙肩弓，架于肩关节上方，有防止肱骨头向上脱位的作用。胸锁关节由锁骨胸骨端与胸骨锁切迹及第1肋软骨构成；肩关节由肱骨头与肩胛骨关节盂构成；肩锁关节由锁骨肩峰端与肩峰构成；盂肱关节即肩关节"},{"q":"由锁骨的胸骨端与胸骨的锁切迹及第1肋软骨的上面构成","o":["胸锁关节","肩关节","肩锁关节","喙肩弓","盂肱关节"],"a":0,"e":"胸锁关节由锁骨胸骨端与胸骨锁切迹及第1肋软骨上面共同构成，属多轴关节，关节囊坚韧，并以此支点扩大上肢活动范围。肩锁关节由锁骨肩峰端与肩峰关节面构成；肩关节即盂肱关节，由肱骨头与关节盂构成；喙肩弓由喙肩韧带与喙突、肩峰构成"},{"q":"由肩胛骨的肩峰与锁骨的肩峰端构成","o":["胸锁关节","肩关节","肩锁关节","喙肩弓","盂肱关节"],"a":2,"e":"肩锁关节由锁骨肩峰端与肩峰的关节面构成，属平面关节，是肩胛骨活动的支点，上方有肩锁韧带加强、下方有喙锁韧带相连。胸锁关节由锁骨胸骨端与胸骨锁切迹及第1肋软骨构成；肩关节即盂肱关节，由肱骨头与关节盂构成；喙肩弓由喙肩韧带与喙突、肩峰构成"},{"q":"双侧收缩使头后仰的肌是","o":["胸锁乳突肌","二腹肌","前斜角肌","颈阔肌","肩胛舌骨肌"],"a":0,"e":"胸锁乳突肌起自胸骨柄前面和锁骨胸骨端，止于颞骨乳突，两侧同时收缩使头后仰，一侧收缩使头向同侧倾斜、脸转向对侧。二腹肌上提舌骨或降下颌；前斜角肌双侧收缩使颈前屈；颈阔肌拉口角及下颌向下；肩胛舌骨肌下拉舌骨"},{"q":"双侧收缩使颈前屈的肌是","o":["胸锁乳突肌","二腹肌","前斜角肌","颈阔肌","肩胛舌骨肌"],"a":2,"e":"前斜角肌起自第3～6颈椎横突前结节，止于第1肋上面，双侧收缩使颈前屈，单侧收缩使颈侧屈，并可上提第1、2肋助吸气。胸锁乳突肌双侧收缩使头后仰；二腹肌上提舌骨；颈阔肌降口角、使颈部皮肤起皱；肩胛舌骨肌下拉舌骨"},{"q":"收缩时降口角，并使颈部出现皱褶的肌是","o":["胸锁乳突肌","二腹肌","前斜角肌","颈阔肌","肩胛舌骨肌"],"a":3,"e":"颈阔肌为颈部浅筋膜内的皮肌，起自胸大肌和三角肌表面筋膜，止于口角、下颌骨下缘及面下部皮肤，收缩时拉口角及下颌向下并使颈部皮肤起皱褶。胸锁乳突肌一侧收缩使头转向对侧；前斜角肌使颈前屈；二腹肌、肩胛舌骨肌作用于舌骨与下颌"},{"q":"由肱骨小头与桡骨头关节凹构成","o":["肱尺关节","肱桡关节","桡尺近侧关节","桡侧远侧关节","前臂骨间膜"],"a":1,"e":"肱桡关节由肱骨小头与桡骨头关节凹构成，是肘关节的组成部分，可作屈伸和旋前旋后运动。肱尺关节由肱骨滑车与尺骨滑车切迹构成；桡尺近侧关节由桡骨头环状关节面与尺骨桡切迹构成；桡尺远侧关节由尺骨头与桡骨尺切迹及关节盘构成；前臂骨间膜为连结尺桡骨的纤维膜"},{"q":"由肱骨滑车与尺骨滑车切迹构成","o":["肱尺关节","肱桡关节","桡尺近侧关节","桡侧远侧关节","前臂骨间膜"],"a":0,"e":"肱尺关节由肱骨滑车与尺骨滑车切迹构成，是肘关节运动的主要部分，仅作屈伸运动。肱桡关节由肱骨小头与桡骨关节凹构成；桡尺近侧关节由桡骨环状关节面与尺骨桡切迹构成；桡尺远侧关节由尺骨头与桡骨尺切迹及关节盘构成；前臂骨间膜为骨间连结"},{"q":"由桡骨头环状关节面与尺骨的桡切迹构成","o":["肱尺关节","肱桡关节","桡尺近侧关节","桡侧远侧关节","前臂骨间膜"],"a":2,"e":"桡尺近侧关节由桡骨头环状关节面与尺骨桡切迹构成，与桡尺远侧关节联合可使前臂旋前和旋后。肱尺关节由肱骨滑车与尺骨滑车切迹构成；肱桡关节由肱骨小头与桡骨关节凹构成；桡尺远侧关节由尺骨头与桡骨尺切迹及关节盘构成；前臂骨间膜为连结尺桡骨的纤维膜"},{"q":"由大多角骨与第1掌骨底构成","o":["腕骨间关节","拇指腕掌关节","掌指关节","指骨间关节","腕关节"],"a":1,"e":"拇指腕掌关节由大多角骨与第1掌骨底构成，属鞍状关节，为灵长目动物所特有，可作屈伸、收展、环转和对掌运动。腕骨间关节由相邻腕骨构成；掌指关节由掌骨头与近节指骨底构成；指骨间关节由相邻指骨构成；腕关节由近侧列腕骨与桡骨及关节盘构成"},{"q":"由相邻各腕骨之间的关节面构成","o":["腕骨间关节","拇指腕掌关节","掌指关节","指骨间关节","腕关节"],"a":0,"e":"腕骨间关节由相邻各腕骨之间的关节面构成，分近侧列、远侧列腕骨间关节和腕中关节，属微动关节，只能作轻微滑动和转动。拇指腕掌关节由大多角骨与第1掌骨底构成；掌指关节由掌骨头与近节指骨底构成；指骨间关节由相邻指骨构成；腕关节由近侧列腕骨与桡骨及关节盘构成"},{"q":"由掌骨头与近节指骨底构成","o":["腕骨间关节","拇指腕掌关节","掌指关节","指骨间关节","腕关节"],"a":2,"e":"掌指关节共5个，由掌骨头与近节指骨底构成，关节囊薄而松弛，两侧有侧副韧带加强，屈指时紧张、伸指时松弛。腕骨间关节由相邻腕骨构成；拇指腕掌关节由大多角骨与第1掌骨底构成；指骨间关节由相邻指骨构成；腕关节由近侧列腕骨与桡骨及关节盘构成"},{"q":"输卵管结扎常用部位是","o":["输卵管子宫部","输卵管峡","输卵管壶腹","输卵管漏斗","输卵管伞"],"a":1,"e":"输卵管峡短而直、管壁较厚，是输卵管结扎术的常用部位。输卵管子宫部为穿过子宫壁的部分；壶腹部粗长弯曲、血供丰富，是卵子受精部位及异位妊娠好发处；漏斗部末端有输卵管腹腔口；输卵管伞为腹腔口边缘的突起，是手术中辨认输卵管的标志"},{"q":"开口于腹膜腔的是","o":["输卵管子宫部","输卵管峡","输卵管壶腹","输卵管漏斗","输卵管伞"],"a":3,"e":"输卵管漏斗末端中央有输卵管腹腔口，开口于腹膜腔，女性腹膜腔借此经输卵管、子宫、阴道与外界相通。输卵管子宫部穿子宫壁开口于子宫腔；峡部短直为结扎常用部位；壶腹部为受精部位；输卵管伞为腹腔口边缘的突起，是辨认标志而非开口本身"},{"q":"手术时辨认输卵管的标志是","o":["输卵管子宫部","输卵管峡","输卵管壶腹","输卵管漏斗","输卵管伞"],"a":4,"e":"输卵管伞为输卵管腹腔口边缘的细长突起，覆盖于卵巢表面，其中卵巢伞较长且内面沟较深，是手术中辨认输卵管的标志。输卵管子宫部穿子宫壁；峡部短直为结扎部位；壶腹部粗长弯曲为受精部位；漏斗部为末端膨大部，其腹腔口通腹膜腔"},{"q":"动眼神经支配","o":["上睑提肌","外直肌","上斜肌","眼轮匝肌","颞肌"],"a":0,"e":"动眼神经支配上睑提肌、上直肌、内直肌、下直肌和下斜肌，并含副交感纤维支配瞳孔括约肌和睫状肌，损伤后出现上睑下垂、瞳孔散大及眼外斜视。外直肌由展神经支配；上斜肌由滑车神经支配；眼轮匝肌由面神经支配；颞肌由下颌神经支配"},{"q":"展神经支配","o":["上睑提肌","外直肌","上斜肌","眼轮匝肌","颞肌"],"a":1,"e":"展神经支配眼外直肌，使瞳孔转向外侧，损伤后眼球不能外展。上睑提肌和其余眼外肌多由动眼神经支配；上斜肌由滑车神经支配，使瞳孔转向下外；眼轮匝肌由面神经支配以闭合眼裂；颞肌由三叉神经下颌神经支配，作用为上提下颌骨"},{"q":"滑车神经支配","o":["上睑提肌","外直肌","上斜肌","眼轮匝肌","颞肌"],"a":2,"e":"滑车神经起自中脑下丘平面的滑车神经核，绕大脑脚外侧前行，经眶上裂入眶支配上斜肌，使其收缩时瞳孔转向下外方。外直肌由展神经支配；上睑提肌由动眼神经支配；眼轮匝肌由面神经支配；颞肌由下颌神经支配"},{"q":"中脑以中脑中管分为背侧部和腹侧部两部分，腹侧部称为","o":["大脑脚","大脑脚底","被盖部","顶盖","基底部"],"a":0,"e":"中脑内部借中脑导水管分为背侧的顶盖和腹侧的大脑脚，大脑脚又被黑质分为腹侧的大脑脚底和背侧的被盖。被盖位于黑质背侧而非腹侧部；大脑脚底只是大脑脚的一部分；顶盖为背侧部；基底部为脑桥的结构分法，不用于中脑"},{"q":"脑桥斜方体的背侧部称为","o":["大脑脚","大脑脚底","被盖部","顶盖","基底部"],"a":2,"e":"脑桥内部结构以斜方体为界，分为腹侧的脑桥基底部和背侧的脑桥被盖部，内侧丘系纵穿斜方体后行于被盖腹外侧。大脑脚、大脑脚底和顶盖均为中脑的分部；基底部位于斜方体腹侧而非背侧"},{"q":"中脑黑质的腹侧部分称为","o":["大脑脚","大脑脚底","被盖部","顶盖","基底部"],"a":1,"e":"大脑脚被黑质分为腹侧的大脑脚底和背侧的被盖，黑质位于两者之间，大脑脚底自内向外有额桥束、锥体束和顶枕颞桥束下行。大脑脚为包含黑质的整体结构；被盖位于黑质背侧；顶盖为中脑背侧部；基底部为脑桥的分部"},{"q":"防止子宫脱垂的是","o":["子宫主韧带","子宫阔韧带","子宫圆韧带","子宫骶韧带","骨盆漏斗韧带"],"a":0,"e":"子宫主韧带由结缔组织和平滑肌构成，位于阔韧带基部，连于子宫颈两侧与盆侧壁之间，强韧地固定子宫颈，是防止子宫脱垂的主要结构。子宫圆韧带维持子宫前倾；阔韧带限制子宫向两侧移位；骶子宫韧带向后上牵引宫颈、协同维持前倾前屈；骨盆漏斗韧带悬吊卵巢"},{"q":"维持子宫前倾的是","o":["子宫主韧带","子宫阔韧带","子宫圆韧带","子宫骶韧带","骨盆漏斗韧带"],"a":2,"e":"子宫圆韧带起自子宫体前外侧、输卵管子宫口下方，穿腹股沟管止于阴阜和大阴唇皮下，向前下方牵引子宫体，是维持子宫前倾的主要结构。子宫主韧带固定宫颈、防脱垂；阔韧带限制侧移；骶子宫韧带向后上牵引宫颈、维持前屈；骨盆漏斗韧带悬吊卵巢"},{"q":"限制子宫向两侧移位的是","o":["子宫主韧带","子宫阔韧带","子宫圆韧带","子宫骶韧带","骨盆漏斗韧带"],"a":1,"e":"子宫阔韧带为覆盖子宫前后面的腹膜向两侧延伸至盆侧壁和盆底形成的双层腹膜皱襞，略呈冠状位，可限制子宫向两侧移动。圆韧带维持前倾；主韧带固定宫颈、防脱垂；骶子宫韧带向后上牵引宫颈；骨盆漏斗韧带（卵巢悬韧带）悬吊卵巢"},{"q":"两侧胸膜前返折线之间的区域是","o":["心包区","胸膜隐窝","膈胸膜","肋膈隐窝","肺韧带"],"a":0,"e":"在第4胸肋关节平面以下，两侧胸膜前返折线分开，形成胸骨体下部及左侧第4、5肋软骨后方的三角形区，即心包区，心包由此直接贴近胸壁。第2胸肋关节以上两侧返折线之间为胸腺区；肋膈隐窝为肋胸膜与膈胸膜返折处；肺韧带为脏、壁胸膜在肺根下方融合所成"},{"q":"肋胸膜与膈胸膜相互移行处称为","o":["心包区","胸膜隐窝","膈胸膜","肋膈隐窝","肺韧带"],"a":3,"e":"肋膈隐窝由肋胸膜与膈胸膜返折移行形成，呈半环形，左右各一，是胸膜隐窝中位置最低、容量最大者，深约两个肋间隙，胸膜积液常先积存于此。肋纵隔隐窝为纵隔胸膜与肋胸膜移行处；膈纵隔隐窝位于膈胸膜与纵隔胸膜之间，仅见于左侧"},{"q":"脏胸膜和壁胸膜移行所形成的结构是","o":["心包区","胸膜隐窝","膈胸膜","肋膈隐窝","肺韧带"],"a":4,"e":"脏、壁胸膜在肺根表面及下方互相移行，两层在两肺根下方融合形成三角形皱襞，即肺韧带，将肺固定于纵隔。胸膜隐窝为壁胸膜返折移行处的胸膜腔，深吸气时肺缘不进入；肋膈隐窝为肋胸膜与膈胸膜返折形成；膈胸膜为壁胸膜贴膈的部分"},{"q":"属于前庭小脑的是","o":["小脑前叶","小脑后叶","小脑蚓部和中间部","小脑体的外侧部","绒球小结叶"],"a":4,"e":"绒球小结叶占据后外侧裂，进化上出现最早，构成原小脑，主要与前庭神经核和前庭神经联系，又称前庭小脑，主管躯干肌运动、眼球运动协调和身体平衡。小脑前叶和后叶为解剖分区；小脑蚓部和中间部主要接受脊髓传入，属脊髓小脑；小脑体外侧部与大脑皮质联系，属大脑小脑"},{"q":"属于脊髓小脑的是","o":["小脑前叶","小脑后叶","小脑蚓部和中间部","小脑体的外侧部","绒球小结叶"],"a":2,"e":"小脑体内侧区和中间区构成旧小脑，主要接受脊髓小脑前、后束传入的本体感觉，又称脊髓小脑，经顶核和中间核影响肌张力。绒球小结叶为前庭小脑；小脑体外侧部与大脑皮质构成环路，属大脑小脑；小脑前叶和后叶为解剖学分部而非功能分区"},{"q":"属于大脑小脑的是","o":["小脑前叶","小脑后叶","小脑蚓部和中间部","小脑体的外侧部","绒球小结叶"],"a":3,"e":"小脑体外侧区进化上出现最晚，构成新小脑，与大脑皮质同步发展并构成纤维联系环路，故称大脑小脑，参与运动的计划和协调。绒球小结叶为前庭小脑；小脑蚓部和中间部属脊髓小脑；小脑前叶和后叶为解剖分区，均不属大脑小脑"},{"q":"喉室位于","o":["声门下腔","前庭裂","喉中间腔","喉腔","喉前庭"],"a":2,"e":"喉中间腔为前庭襞与声襞之间的喉腔部分，向两侧经前庭襞与声襞间的裂隙突入喉室。声门下腔为声襞以下的部分；前庭裂为两侧前庭襞之间的裂隙；喉腔为整体概念；喉前庭为喉口与前庭襞之间的部分，上宽下窄呈漏斗状"},{"q":"前庭襞之间的裂隙称为","o":["声门下腔","前庭裂","喉中间腔","喉腔","喉前庭"],"a":1,"e":"两侧前庭襞之间的裂隙称前庭裂，较声门裂宽。声门下腔为声襞下方的喉腔；喉中间腔为前庭襞与声襞之间部分；喉腔为整体概念；喉前庭为喉口与前庭襞之间部分。声门裂是两侧声襞与杓状软骨之间的裂隙，较前庭裂长而窄，为喉腔最狭窄处"},{"q":"弹性圆锥位于","o":["声门下腔","前庭裂","喉中间腔","喉腔","喉前庭"],"a":3,"e":"弹性圆锥为喉腔内呈圆锥形的弹性纤维膜，又称环甲膜，起自甲状软骨前角内面，向后下止于杓状软骨声带突和环状软骨上缘，其上缘游离增厚称声韧带。声门下腔为声襞以下部分；前庭裂和喉中间腔为喉腔的分部或裂隙；喉前庭为喉口与前庭襞之间部分，均非其所在的整体定位"},{"q":"古小脑接受的纤维是","o":["前庭神经或前庭神经核的纤维","脊髓纤维","脑桥纤维","小脑皮质的纤维","黑质的纤维"],"a":0,"e":"古小脑（前庭小脑、原小脑）主要接受同侧前庭神经的初级平衡觉纤维及前庭神经核经小脑下脚的传入纤维，调节躯干肌运动、协调眼球运动并维持身体平衡。脊髓纤维主要传入旧小脑；脑桥纤维（皮质脑桥束经脑桥核中继）传入新小脑；黑质纤维与小脑皮质无此类直接传入"},{"q":"旧小脑接受的纤维是","o":["前庭神经或前庭神经核的纤维","脊髓纤维","脑桥纤维","小脑皮质的纤维","黑质的纤维"],"a":1,"e":"旧小脑（脊髓小脑）主要接受脊髓小脑前、后束经小脑上、下脚传入的本体感觉冲动，以调节肌张力。前庭神经及前庭神经核纤维传入原（古）小脑；脑桥纤维（经脑桥核中继的皮质脑桥束）传入新小脑；黑质不属于小脑主要传入；小脑皮质纤维实为传向小脑核的传出通路"},{"q":"新小脑接受的纤维是","o":["前庭神经或前庭神经核的纤维","脊髓纤维","脑桥纤维","小脑皮质的纤维","黑质的纤维"],"a":2,"e":"新小脑（大脑小脑）主要接受皮质脑桥束在脑桥核中继后交叉、经小脑中脚传入的纤维，参与调控骨骼肌的精细运动。脊髓纤维传入旧小脑；前庭神经及前庭神经核纤维传入古（原）小脑；黑质与小脑的联系为小脑-黑质环路、非主要传入；小脑皮质纤维为传出"},{"q":"汇入头臂静脉的是","o":["面静脉","甲状腺下静脉","颞浅静脉","颈静脉弓","颈前静脉"],"a":1,"e":"头臂静脉由锁骨下静脉与颈内静脉汇合而成，还接受椎静脉、胸廓内静脉、肋间最上静脉和甲状腺下静脉等。面静脉注入颈内静脉；颞浅静脉与下颌后静脉汇合后注入颈外静脉；颈静脉弓由左右颈前静脉吻合而成；颈前静脉注入颈外静脉末端或锁骨下静脉"},{"q":"汇入颈内静脉的是","o":["面静脉","甲状腺下静脉","颞浅静脉","颈静脉弓","颈前静脉"],"a":0,"e":"面静脉起自内眦静脉，在面动脉后方下行，于下颌角下方接受下颌后静脉前支，至舌骨大角附近注入颈内静脉。甲状腺下静脉注入头臂静脉；颞浅静脉参与构成下颌后静脉并注入颈外静脉；颈静脉弓和颈前静脉注入颈外静脉末端或锁骨下静脉"},{"q":"汇入颈外静脉的是","o":["面静脉","甲状腺下静脉","颞浅静脉","颈静脉弓","颈前静脉"],"a":4,"e":"颈前静脉起自颏下方的浅静脉，沿颈前正中线两侧下行，注入颈外静脉末端或锁骨下静脉，左右颈前静脉在胸骨柄上方常吻合成颈静脉弓。面静脉注入颈内静脉；甲状腺下静脉注入头臂静脉；颞浅静脉参与构成下颌后静脉，颈静脉弓只是左右颈前静脉的吻合而非独立汇入者"},{"q":"舌淋巴管注入的是","o":["气管旁淋巴结","颏下淋巴结","下颌下淋巴结","锁骨上淋巴结","斜角肌淋巴结"],"a":1,"e":"颏下淋巴结位于颏下部，引流舌尖、下唇中部和颏部的淋巴。下颌下淋巴结位于下颌下腺附近，引流面部和口腔器官的淋巴；气管旁淋巴结沿喉返神经排列，引流喉、甲状腺、气管和食管；锁骨上淋巴结接受颈外侧深淋巴结输出；斜角肌淋巴结属颈外侧下深淋巴结群"},{"q":"甲状腺淋巴管注入的是","o":["气管旁淋巴结","颏下淋巴结","下颌下淋巴结","锁骨上淋巴结","斜角肌淋巴结"],"a":0,"e":"气管旁淋巴结位于气管与食管之间的侧沟内，沿喉返神经排列，引流喉、甲状腺、气管和食管的淋巴，其肿大压迫喉返神经可致声音嘶哑。甲状腺淋巴结位于甲状腺峡部前面，输出注入气管前、气管旁及颈外侧上深淋巴结；颏下淋巴结引流舌尖等；锁骨上和斜角肌淋巴结为颈深淋巴结群"},{"q":"喉淋巴管注入的是","o":["气管旁淋巴结","颏下淋巴结","下颌下淋巴结","锁骨上淋巴结","斜角肌淋巴结"],"a":0,"e":"气管旁淋巴结引流喉、甲状腺、气管和食管的淋巴，喉的淋巴管注入此群，其输出注入颈外侧下深淋巴结。气管前淋巴结引流喉、甲状腺和气管颈部淋巴并注入气管旁淋巴结；颏下淋巴结引流舌尖、下唇中部和颏部；下颌下淋巴结引流面部和口腔器官；锁骨上淋巴结为颈深淋巴结群"},{"q":"属于鞍状关节，可作屈伸、收展、环转和对掌运动的关节是","o":["桡腕关节","拇指腕掌关节","掌指关节","指骨间关节","腕骨间关节"],"a":1,"e":"拇指腕掌关节由大多角骨与第1掌骨底构成，属鞍状关节，两关节面均呈鞍状、有两个运动轴，可作屈、伸、收、展、环转和对掌运动，为灵长类特有。桡腕关节为椭圆关节；掌指关节近似椭圆关节；指骨间关节为滑车（屈戌）关节；腕骨间关节为平面关节"},{"q":"属于滑车关节，可作屈、伸运动的关节是","o":["桡腕关节","拇指腕掌关节","掌指关节","指骨间关节","腕骨间关节"],"a":3,"e":"指骨间关节由相邻两节指骨的底与滑车构成，属典型的滑车（屈戌）关节，只能作屈、伸运动，关节囊松弛、两侧有韧带加强。拇指腕掌关节为鞍状关节、可作对掌；桡腕关节为椭圆关节、可作环转；掌指关节为椭圆关节；腕骨间关节为平面关节"},{"q":"属椭圆关节，可作屈、伸、收、展和环转运动的关节是","o":["桡腕关节","拇指腕掌关节","掌指关节","指骨间关节","腕骨间关节"],"a":0,"e":"桡腕关节由桡骨腕关节面与舟、月、三角骨构成，属椭圆关节，可沿冠状轴作屈伸、矢状轴作收展，并可作环转运动。拇指腕掌关节为鞍状关节且能对掌；指骨间关节为滑车关节、只能屈伸；掌指关节近椭圆关节；腕骨间关节为平面关节、运动微弱"},{"q":"属于上丘脑的是","o":["丘脑间黏合","外侧膝状体","缰连合","未定带","视交叉"],"a":2,"e":"上丘脑居第三脑室顶后部的周围，包括松果体、缰连合、缰三角、丘脑髓纹和后连合。丘脑间黏合连接两侧背侧丘脑，属背侧丘脑；外侧膝状体为后丘脑的视觉中继站；未定带属底丘脑；视交叉属下丘脑的结构"},{"q":"属于下丘脑的是","o":["丘脑间黏合","外侧膝状体","缰连合","未定带","视交叉"],"a":4,"e":"下丘脑位于背侧丘脑前下方，包括视交叉、灰结节、漏斗、垂体和乳头体等，分为视前区、视上区、结节区和乳头区。丘脑间黏合属背侧丘脑；外侧膝状体属后丘脑；缰连合属上丘脑；未定带属底丘脑，均不属下丘脑"},{"q":"属于背侧丘脑的是","o":["丘脑间黏合","外侧膝状体","缰连合","未定带","视交叉"],"a":0,"e":"背侧丘脑为一对卵圆形灰质团块，两侧借丘脑间黏合相连，前端为丘脑前结节，后端为丘脑枕。外侧膝状体属后丘脑，为视觉中继站；缰连合属上丘脑；未定带属底丘脑；视交叉属下丘脑，均不属背侧丘脑本体"},{"q":"大脑后动脉供应","o":["额叶内侧面","内囊膝","外侧膝状体","枕叶内侧面","脑桥"],"a":3,"e":"大脑后动脉为基底动脉终支，绕大脑脚向后沿海马旁回钩转至颞叶和枕叶内侧面，皮质支供应颞叶内侧面、底面及枕叶，中央支供应背侧丘脑和内侧膝状体等。额叶内侧面由大脑前动脉供应；内囊膝由大脑中动脉豆纹动脉供应；外侧膝状体主要由脉络膜前动脉供应；脑桥由基底动脉分支供应"},{"q":"大脑前动脉供应","o":["额叶内侧面","内囊膝","外侧膝状体","枕叶内侧面","脑桥"],"a":0,"e":"大脑前动脉皮质支分布于顶枕沟以前的半球内侧面、额叶底面一部分及额顶两叶上外侧面的一部，故供应额叶内侧面，中央支供应壳、尾状核前部和内囊下部。内囊膝由大脑中动脉豆纹动脉供应；枕叶内侧面和外侧膝状体主要属大脑后动脉供血区；脑桥由基底动脉分支供应"},{"q":"大脑中动脉供应","o":["额叶内侧面","内囊膝","外侧膝状体","枕叶内侧面","脑桥"],"a":1,"e":"大脑中动脉途经前穿质时发出豆纹动脉等中央支，营养尾状核、豆状核及内囊膝和后肢前部，皮质支供应大脑半球上外侧面大部。额叶内侧面由大脑前动脉供应；枕叶内侧面由大脑后动脉供应；外侧膝状体主要不属大脑中动脉供血；脑桥由基底动脉分支供应"}];
